  ["Administración"] = "Amministrazione",
  ["Administración enseña cómo va la conexión, con una prueba de mensajes."] = "Amministrazione mostra come va la connessione, con una prova dei messaggi.",
  ["Administración: al cambiar de idioma ya no sale «Una acción de interfaz ha fallado por culpa de un accesorio». El juego no deja que un accesorio recargue la interfaz: escribe /reload."] = "Amministrazione: cambiando lingua non compare più «Azione dell'interfaccia non riuscita a causa di un AddOn». Il gioco non permette a un addon di ricaricare l'interfaccia: scrivi /reload.",
  ["Ahora no"] = "Non ora",
  ["Ahora no hay nadie más de la hermandad conectado. Cuando haya alguien, sale aquí; si tiene BlazonGuild, con «Retar»."] = "Ora non c'è nessun altro della gilda connesso. Quando ci sarà qualcuno, apparirà qui; se ha BlazonGuild, con «Sfida».",
  ["Ahora no puede"] = "Ora non può",
  ["Ahora organizas en %s"] = "Ora organizzi in %s",
  ["Ahora pulsa dónde va %s: un grupo, «Sin grupo» o «Reserva». Si pulsas a otro jugador, se cambian el sitio."] = "Ora premi dove va %s: un gruppo, «Senza gruppo» o «Riserva». Se premi un altro giocatore, si scambiano il posto.",
  ["Ahora tienen %s conectados, %s con BlazonGuild."] = "Ora hanno %s connessi, %s con BlazonGuild.",
  ["Ahora: %d %s y %d %s."] = "Ora: %d %s e %d %s.",
  ["Ajustes del maestro"] = "Impostazioni del capogilda",
  ["Al abrir el mapa del mundo la ventana se minimiza sola, y vuelve al cerrarlo."] = "Quando apri la mappa del mondo la finestra si riduce da sola, e torna quando la chiudi.",
  ["Al hablar con un posadero, un aviso te propone una partida. Todo por puntos: aquí no se mueve oro."] = "Quando parli con un oste, un avviso ti propone una partita. Tutto a punti: qui non si muove oro.",
  ["Al sortear, los mejores de la Arena son cabezas de serie; el resto se sortea con /roll, que veréis en el chat."] = "Al sorteggio, i migliori dell'Arena sono teste di serie; il resto si sorteggia con /roll, che vedrete in chat.",
  ["Al terminar, quien la dirigió escribe cómo fue. Queda en la crónica de la hermandad con quién estuvo."] = "Alla fine, chi l'ha diretta scrive com'è andata. Resta nella cronaca della gilda con chi c'era.",
  ["Al terminar, quien la dirigió escribe el parte, que queda en la crónica."] = "Alla fine, chi l'ha diretta scrive il rapporto, che resta nella cronaca.",
  ["Alguien"] = "Qualcuno",
  ["Alianza"] = "Alleanza",
  ["Alianza creada"] = "Alleanza creata",
  ["Alianza «%s»"] = "Alleanza «%s»",
  ["Alianza, pestaña «Cartas y avisos»: cartas del líder a los maestros (con quién las ha leído), «puertas abiertas» para mandar a los nuevos a una hermandad y ocultar a alguien en los chats comunes."] = "Alleanza, scheda «Lettere e avvisi»: lettere del capo ai maestri (con chi le ha lette), «porte aperte» per mandare i nuovi a una gilda e nascondere qualcuno nelle chat comuni.",
  ["Alter de %s"] = "Alt di %s",
