  ["Apuntar a mano"] = "Annota a mano",
  ["Apuntar en el libro"] = "Annota nel registro",
  ["Apuntar en la Tesorería el oro del correo (solo lee lo que hace el juego)"] = "Annotare in Tesoreria l'oro della posta (legge solo ciò che fa il gioco)",
  ["Apuntar mis muertes y bajas: no"] = "Annotare le mie morti e uccisioni: no",
