  ["Así funcionan los honores"] = "Come funzionano gli onori",
  ["Así tu hermandad te ve en la Armería aunque estéis lejos: lo que llevas puesto y su nivel, lo mismo que ve quien te inspecciona en el juego."] = "Così la tua gilda ti vede nell'Armeria anche da lontano: cosa indossi e il suo livello, come chi ti ispeziona nel gioco.",
  ["Ausente"] = "Assente",
  ["Automático (el del juego)"] = "Automatico (quella del gioco)",
  ["Autoprueba"] = "Autotest",
  ["Autoprueba (Administración o /bg autoprueba): comprueba el addon en tu juego y te da un informe para copiar."] = "Autotest (Amministrazione o /bg autoprueba): controlla l'addon nel tuo gioco e ti dà un rapporto da copiare.",
  ["Avisamos a %s. En cuanto contesten, estaréis dentro."] = "Abbiamo avvisato %s. Appena rispondono, sarete dentro.",
  ["Avisamos a todos los llamados de que no se hace."] = "Avvisiamo tutti i convocati che non si fa.",
  ["Aviso final"] = "Ultimo avviso",
  ["Avisos %s"] = "Avvisi %s",
  ["Avisos acumulados: %s de 3. Al tercero se abre un caso que decide el maestro."] = "Avvisi accumulati: %s di 3. Al terzo si apre un caso che decide il capogilda.",
