  ["Añadir un combate a la velada"] = "Aggiungi un combattimento alla serata",
  ["Aún nadie"] = "Ancora nessuno",
  ["Aún nadie ha cazado a un buscado."] = "Nessuno ha ancora cacciato un ricercato.",
  ["Aún nadie ha jugado una partida entre miembros. Las de práctica contra la casa no cuentan."] = "Nessuno ha ancora giocato una partita tra membri. Quelle di allenamento contro la casa non contano.",
  ["Aún nadie ha votado. "] = "Nessuno ha ancora votato. ",
  ["Aún nadie, aparte del jefe."] = "Ancora nessuno, a parte il capo.",
  ["Aún nadie."] = "Ancora nessuno.",
  ["Aún nadie. Cuando alguien entra, dice quién le trajo."] = "Ancora nessuno. Chi entra dice chi l'ha portato.",
  ["Aún ninguna. Aquí salen las raids de BlazonGuild que ya empezaron, con cuántos fueron."] = "Ancora nessuna. Qui compaiono le incursioni di BlazonGuild già iniziate, con quanti sono andati.",
  ["Aún ninguno. Cuando la hermandad mate a un jefe de esta banda (con la mayoría del grupo de la hermandad), el addon de quien estaba allí lo apunta solo."] = "Ancora nessuno. Quando la gilda uccide un boss di questa incursione (con il gruppo in gran parte della gilda), l'addon di chi era lì lo annota da solo.",
  ["Aún no compartes tu equipo. Pulsa «Compartir mi equipo» y tu hermandad verá lo que llevas puesto (se actualiza solo cuando cambias algo)."] = "Non condividi ancora il tuo equipaggiamento. Premi «Condividi il mio equipaggiamento» e la tua gilda vedrà cosa indossi (si aggiorna da solo quando cambi qualcosa).",
  ["Aún no conocéis ninguna hermandad. Cuando alguien de la vuestra juegue en grupo con alguien de otra hermandad que use BlazonGuild y publique sus cifras, aparecerá aquí."] = "Non conoscete ancora nessuna gilda. Quando qualcuno della vostra giocherà in gruppo con qualcuno di un'altra gilda che usa BlazonGuild e pubblica i suoi numeri, apparirà qui.",
  ["Aún no conocéis otras hermandades. Aparecen al jugar en grupo (mazmorras, bandas, campos de batalla) con alguien de ellas que use BlazonGuild."] = "Non conoscete ancora altre gilde. Compaiono quando giocate in gruppo (istanze, incursioni, campi di battaglia) con qualcuno di loro che usa BlazonGuild.",
  ["Aún no ha pasado nada. Aquí sale cada muerte y cada baja que apuntan los miembros con el addon."] = "Non è ancora successo niente. Qui appare ogni morte e ogni uccisione che annotano i membri con l'addon.",
  ["Aún no ha peleado esta temporada."] = "Non ha ancora combattuto questa stagione.",
  ["Aún no ha respondido nadie."] = "Non ha ancora risposto nessuno.",
  ["Aún no has preguntado nada."] = "Non hai ancora chiesto nulla.",
  ["Aún no hay campeón: el primero que gane un duelo se lleva el cinturón."] = "Ancora nessun campione: il primo che vince un duello prende la cintura.",
  ["Aún no hay cartas. El líder de la alianza escribe aquí a los maestros (y, si quiere, a los capitanes)."] = "Nessuna lettera ancora. Il capo dell'alleanza scrive qui ai maestri (e, se vuole, ai capitani).",
  ["Aún no hay combates esta temporada."] = "Ancora nessun combattimento questa stagione.",
  ["Aún no hay combates esta temporada. Reta a alguien en «Retos», o batíos en duelo desde el juego: el addon de quien pierde lo apunta solo."] = "Ancora nessun combattimento questa stagione. Sfida qualcuno in «Sfide», o duellate dal gioco: l'addon di chi perde lo annota da solo.",
  ["Aún no hay combates.%s"] = "Ancora nessun combattimento.%s",
  ["Aún no hay escuadras. "] = "Ancora nessuna squadra. ",
  ["Aún no hay escuadras. Crea una con un jefe y unos pocos miembros: tendrá su propio chat y podréis llamarla a operaciones."] = "Ancora nessuna squadra. Creane una con un capo e pochi membri: avrà la sua chat e potrete chiamarla alle operazioni.",
  ["Aún no hay escuadras. Las crean los organizadores; cada una tiene su jefe y su propio chat."] = "Ancora nessuna squadra. Le creano gli organizzatori; ognuna ha il suo capo e la sua chat.",
  ["Aún no hay ficha. La escriben los oficiales: a qué os dedicáis, idioma, días de banda y a quién buscáis."] = "Ancora nessuna scheda. La scrivono gli ufficiali: di cosa vi occupate, lingua, giorni di incursione e chi cercate.",
  ["Aún no hay foto del banco. Aparecerá cuando un oficial o un tesorero lo abra con BlazonGuild."] = "Ancora nessuna foto della banca. Apparirà quando un ufficiale o un tesoriere la aprirà con BlazonGuild.",
  ["Aún no hay nadie en este ranking."] = "Ancora nessuno in questa classifica.",
  ["Aún no hay nadie. Para salir aquí, cada uno abre la ventana de su profesión en el juego y dice «Publicar». Escribe arriba un objeto para buscar quién lo fabrica."] = "Ancora nessuno. Per comparire qui, ognuno apre nel gioco la finestra della sua professione e dice «Pubblica». Scrivi sopra un oggetto per trovare chi lo fabbrica.",
  ["Aún no hay ningún cargo."] = "Nessun incarico ancora.",
  ["Aún no hay partes. Quien dirige una operación lo escribe al terminarla."] = "Ancora nessun rapporto. Chi dirige un'operazione lo scrive alla fine.",
  ["Aún no hay tesoreros: los nombra el maestro en «Cuotas». "] = "Ancora nessun tesoriere: li nomina il capogilda in «Quote». ",
  ["Aún no hay torneos. Cualquiera puede crear uno con «Nuevo»: un torneo con cuadro eliminatorio, o una velada con combates anunciados."] = "Ancora nessun torneo. Chiunque può crearne uno con «Nuovo»: un torneo a eliminazione diretta, o una serata con combattimenti annunciati.",
  ["Aún no hemos visto ninguna. En el juego, abre la ventana de tu profesión (por ejemplo, Herrería o Alquimia): BlazonGuild te preguntará si quieres publicarla. Solo la ve tu hermandad."] = "Non ne abbiamo ancora vista nessuna. Nel gioco, apri la finestra della tua professione (per esempio Forgiatura o Alchimia): BlazonGuild ti chiederà se vuoi pubblicarla. La vede solo la tua gilda.",
  ["Aún no se sabe qué lleva."] = "Non si sa ancora cosa indossa.",
  ["Aún no tienes boletos hoy."] = "Oggi non hai ancora biglietti.",
  ["Aún no tienes honores. Cazar buscados, donar, fabricar encargos, traer gente o ir a las raids te sube en los rankings."] = "Non hai ancora onori. Cacciare ricercati, donare, fabbricare ordini, portare gente o andare alle incursioni ti fa salire nelle classifiche.",
  ["Aún sin combates esta temporada."] = "Ancora nessun combattimento in questa stagione.",
  ["Aún sin contacto: llegará cuando se conecte alguien suyo con BlazonGuild."] = "Ancora senza contatto: arriverà quando si connetterà qualcuno dei loro con BlazonGuild.",
