  ["Con %s combates tienes rango: %s (los mejores), %s y %s."] = "Con %s combattimenti hai un rango: %s (i migliori), %s e %s.",
  ["Con 5 combates tienes rango: Oro, Plata o Bronce. El campeón lleva el cinturón, y quien le gane se lo queda."] = "Con 5 combattimenti hai un rango: Oro, Argento o Bronzo. Il campione porta la cintura, e chi lo batte se la prende.",
  ["Con BlazonGuild"] = "Con BlazonGuild",
  ["Con BlazonGuild ahora"] = "Con BlazonGuild ora",
  ["Con la banda ya formada, «Colocar en la banda» mueve a cada uno a su grupo de verdad (el orden dentro del grupo lo pone el juego). Hace falta ser líder o ayudante, y fuera de combate."] = "Con l'incursione già formata, «Colloca nell'incursione» sposta ognuno nel suo gruppo vero (l'ordine dentro il gruppo lo decide il gioco). Serve essere capo o assistente, e fuori combattimento.",
  ["Con mando"] = "Con il controller",
  ["Con mando: BlazonGuild ya no toca nada de la interfaz del juego mientras la de mando está activada."] = "Con il controller: BlazonGuild non tocca più nulla dell'interfaccia del gioco mentre quella del controller è attiva.",
  ["Con una alianza: el maestro la crea en Alianza e invita a otra hermandad; si su maestro acepta, el chat tiene una pestaña para cada una."] = "Con un'alleanza: il capogilda la crea in Alleanza e invita un'altra gilda; se il loro capogilda accetta, la chat ha una scheda per ognuna.",
  ["Concepto (para qué es)"] = "Causale (a cosa serve)",
  ["Conectado"] = "Connesso",
  ["Conectados"] = "Connessi",
  ["Conectados ahora"] = "Connessi ora",
  ["Conexión con tu hermandad"] = "Connessione con la tua gilda",
  ["Consume menos, y todo sigue igual: el addon ocupa casi la mitad de memoria (solo guarda tu idioma), y en una hermandad grande cada actualización de la lista de miembros cuesta varias veces menos y casi no deja basura."] = "Consuma meno e tutto resta uguale: l'addon occupa quasi metà della memoria (tiene solo la tua lingua), e in una gilda grande ogni aggiornamento dell'elenco dei membri costa molte volte meno e non lascia quasi rifiuti.",
  ["Contacto"] = "Contatto",
