  ["Cumbre de Roca Negra superior"] = "Guglia di Roccianera Superiore",
  ["Cuota semanal (oro; 0 = sin cuota)"] = "Quota settimanale (oro; 0 = nessuna quota)",
  ["Cuota semanal opcional: en «Resumen» ves cuánto has dado esta semana y cuánto te falta."] = "Quota settimanale facoltativa: in «Riepilogo» vedi quanto hai dato questa settimana e quanto ti manca.",
  ["Cuota: %s por semana. Esta semana has dado %s%s"] = "Quota: %s a settimana. Questa settimana hai dato %s%s",
  ["Cuota: %s por semana. Esta semana has dado %s: estás al día. ¡Gracias!"] = "Quota: %s a settimana. Questa settimana hai dato %s: sei in regola. Grazie!",
  ["Cuota: %s por semana. Esta semana has dado %s: te faltan %s. Dáselo a un tesorero por comercio o correo."] = "Quota: %s a settimana. Questa settimana hai dato %s: ti mancano %s. Dallo a un tesoriere tramite scambio o posta.",
  ["Cuotas"] = "Quote",
  ["Cuotas de esta semana"] = "Quote di questa settimana",
  ["Cuándo (para que la gente se organice)"] = "Quando (perché la gente si organizzi)",
  ["Cuándo jugamos: %s."] = "Quando giochiamo: %s.",
  ["Cuándo jugáis"] = "Quando giocate",
  ["Cuándo sueles jugar"] = "Quando giochi di solito",
  ["Cuánto (5 = 5 de oro; también 2o 50p)"] = "Quanto (5 = 5 oro; anche 2o 50p)",
  ["Cuántos"] = "Quanti",
  ["Cuántos luchadores como mucho"] = "Numero massimo di combattenti",
  ["Cuántos miembros están listos para cada banda y el historial de raids de la hermandad."] = "Quanti membri sono pronti per ogni incursione e la storia delle incursioni della gilda.",
  ["Cómo fue"] = "Com'è andata",
