  ["Cómo se juega"] = "Come si gioca",
  ["Cómo se juega a los Huesos"] = "Come si gioca a Ossa",
  ["Cómo va la conexión con tu hermandad, qué compartes y los ajustes de la hermandad."] = "Come va la connessione con la tua gilda, cosa condividi e le impostazioni della gilda.",
  ["D"] = "S",
  ["Dale oro a un tesorero por comercio o por correo. Su addon lo apunta solo en el libro, y a ti te llega un «gracias»."] = "Dai oro a un tesoriere per scambio o posta. Il suo addon lo annota da solo nel registro, e ti arriva un «grazie».",
  ["Dar oro"] = "Dare oro",
  ["Datos de tu última sesión, actualizando…"] = "Dati della tua ultima sessione, in aggiornamento…",
  ["Daño"] = "Danni",
  ["De %s, de «%s», %s."] = "Da %s, di «%s», %s.",
  ["De %s, hermandad hermana"] = "Di %s, gilda sorella",
  ["De dónde sale"] = "Da dove viene",
  ["De quién o para quién"] = "Da chi o per chi",
  ["Decidido a mano"] = "Deciso a mano",
  ["Decir a mi hermandad dónde he visto a jugadores de la otra facción, solo cuando un compañero lo pregunte"] = "Dire alla mia gilda dove ho visto giocatori dell'altra fazione, solo quando un compagno lo chiede",
  ["Decisión tomada"] = "Decisione presa",
  ["Defensa"] = "Difesa",
  ["Deja una barra pequeña para ver el juego. Pulsa la barra para volver."] = "Lascia una piccola barra per vedere il gioco. Premi la barra per tornare.",
  ["Dejar de compartir"] = "Smetti di condividere",
  ["Dejar de publicar"] = "Smetti di pubblicare",
  ["Dejar de seguir"] = "Smetti di seguire",
  ["Dejarlo así"] = "Lascia così",
  ["Denuncia enviada"] = "Segnalazione inviata",
  ["Denuncia nueva"] = "Nuova segnalazione",
  ["Denunciar"] = "Segnala",
  ["Denuncias y silencios"] = "Segnalazioni e silenziamenti",
  ["Derrota"] = "Sconfitta",
  ["Desaparece de la lista para todos."] = "Sparisce dalla lista per tutti.",
  ["Desolace"] = "Desolace",
  ["Deutsch"] = "Deutsch",
  ["Devolver"] = "Restituisci",
  ["Directorio de mazmorras con quién de la hermandad tiene el nivel, y buscador de grupo: forma uno o únete por rol desde aquí."] = "Elenco delle istanze con chi della gilda ha il livello, e cerca gruppo: formane uno o unisciti per ruolo da qui.",
  ["Dirige: %s."] = "Guida: %s.",
  ["Donantes"] = "Donatori",
  ["Druida"] = "Druido",
  ["Duelos apuntados en la temporada de la Arena."] = "Duelli annotati nella stagione dell'Arena.",
  ["Duelos de la Arena"] = "Duelli dell'Arena",
  ["Duelos entre miembros de la hermandad, con su clasificación. El resultado lo lee el propio juego al terminar el duelo. Sin apuestas."] = "Duelli tra membri della gilda, con la loro classifica. Il gioco stesso legge il risultato alla fine del duello. Niente scommesse.",
  ["Dun Morogh"] = "Dun Morogh",
  ["Dáselo a un tesorero por comercio o por correo: se apunta solo en la Tesorería. Los tesoreros los nombra el maestro."] = "Dallo a un tesoriere per scambio o posta: si annota da solo nella Tesoreria. I tesorieri li nomina il capogilda.",
  ["Día"] = "Giorno",
  ["Día y hora"] = "Giorno e ora",
  ["Días anteriores:\n%s"] = "Giorni precedenti:\n%s",
  ["Días que dura"] = "Giorni di durata",
  ["Dónde (opcional)"] = "Dove (facoltativo)",
  ["Dónde está la hermandad"] = "Dov'è la gilda",
  ["Dónde está tu hermandad"] = "Dov'è la tua gilda",
  ["Dónde estás"] = "Dove sei",
  ["Echa una partida de dados por puntos: contra la casa para practicar, o retando a alguien de la hermandad. Arena, pestaña «Taberna»."] = "Fai una partita a dadi a punti: contro la casa per allenarti, o sfidando qualcuno della gilda. Arena, scheda «Taverna».",
  ["Editar"] = "Modifica",
  ["Editar ficha"] = "Modifica scheda",
  ["Editar la línea"] = "Modifica la riga",
  ["Editar mi ficha"] = "Modifica la mia scheda",
  ["Editar operación"] = "Modifica operazione",
  ["Editar raid"] = "Modifica incursione",
  ["El Templo de Atal'Hakkar"] = "Il Tempio di Atal'Hakkar",
  ["El artesano"] = "L'artigiano",
  ["El atajo Mayús + tecla de hermandad"] = "La scorciatoia Maiusc + tasto gilda",
  ["El botón de BlazonGuild en la ventana de hermandad del juego"] = "Il pulsante BlazonGuild nella finestra di gilda del gioco",
  ["El canal oculto de la alianza (su chat sigue por los mensajeros)"] = "Il canale nascosto dell'alleanza (la sua chat continua tramite i messaggeri)",
  ["El chat de hermandad del juego no se puede silenciar desde un addon: ahí solo se oculta en BlazonGuild."] = "La chat di gilda del gioco non si può silenziare da un addon: lì si nasconde solo in BlazonGuild.",
  ["El chat de la alianza va también por un canal oculto del juego, así llega aunque falten mensajeros. Y la pestaña «Gestión» reúne los cargos y las invitaciones."] = "La chat dell'alleanza passa anche per un canale nascosto del gioco, così arriva anche se mancano i messaggeri. E la scheda «Gestione» raccoglie incarichi e inviti.",
  ["El chat de oficiales del juego: solo lo leen los rangos con permiso."] = "La chat degli ufficiali del gioco: la leggono solo i ranghi con permesso.",
  ["El equipo, los talentos, los atributos y las profesiones de cada miembro, con sus tooltips, sin salir del juego."] = "L'equipaggiamento, i talenti, le statistiche e le professioni di ogni membro, con i loro tooltip, senza uscire dal gioco.",
  ["El escudo de honor en las ventanas de chat del juego"] = "Lo stemma d'onore nelle finestre di chat del gioco",
  ["El grupo de %s para %s no puede llevarte esta vez."] = "Il gruppo di %s per %s non può portarti questa volta.",
  ["El honor"] = "L'onore",
  ["El idioma nuevo se aplica al recargar la interfaz."] = "La nuova lingua si applica ricaricando l'interfaccia.",
  ["El jefe tiene que ser de tu hermandad."] = "Il capo deve essere della tua gilda.",
  ["El juego"] = "Il gioco",
  ["El juego no deja inspeccionarle ahora."] = "Il gioco non permette di ispezionarlo ora.",
  ["El juego no deja que un accesorio recargue la interfaz por sí solo."] = "Il gioco non permette a un addon di ricaricare l'interfaccia da solo.",
  ["El juego no devolvió la tirada (/roll). Vuelve a pulsar «Sortear y empezar»."] = "Il gioco non ha restituito il tiro (/roll). Premi di nuovo «Sorteggia e inizia».",
  ["El juego no respondió; acércate y vuelve a probar."] = "Il gioco non ha risposto; avvicinati e riprova.",
  ["El juego solo deja inspeccionar de cerca (unos 30 metros). Desde lejos solo se ve el equipo de quien tiene BlazonGuild: acércate a él, o pídele que lo instale."] = "Il gioco permette di ispezionare solo da vicino (circa 30 metri). Da lontano si vede solo l'equipaggiamento di chi ha BlazonGuild: avvicinati, o chiedigli di installarlo.",
  ["El juego tardaba demasiado en responder; vuelve a pulsar."] = "Il gioco ci metteva troppo a rispondere; premi di nuovo.",
  ["El juego todavía no ha enviado la lista de miembros. Aparecerá en unos segundos."] = "Il gioco non ha ancora inviato la lista dei membri. Apparirà tra qualche secondo.",
  ["El libro está vacío. Cuando alguien dé oro a un tesorero por comercio o correo, se apunta aquí solo."] = "Il registro è vuoto. Quando qualcuno darà oro a un tesoriere per scambio o posta, si annoterà qui da solo.",
  ["El líder"] = "Il leader",
  ["El líder de «%s» ha sacado a %s de la alianza."] = "Il leader di «%s» ha tolto %s dall'alleanza.",
  ["El líder puede llamar a las armas a toda la alianza y darle una clave nueva."] = "Il leader può chiamare alle armi tutta l'alleanza e darle una nuova chiave.",
  ["El líder puede ocultar a alguien en los chats comunes; la lista la ven los organizadores."] = "Il capo può nascondere qualcuno nelle chat comuni; l'elenco lo vedono gli organizzatori.",
  ["El maestro"] = "Il capogilda",
  ["El maestro decide sobre %s"] = "Il capogilda decide su %s",
  ["El maestro ha decidido no mostrar los donantes."] = "Il capogilda ha deciso di non mostrare i donatori.",
  ["El maestro ha decidido que el libro solo lo vean los oficiales y los tesoreros."] = "Il capogilda ha deciso che il registro lo vedano solo gli ufficiali e i tesorieri.",
  ["El maestro la crea e invita a alguien de otra hermandad que tenga BlazonGuild. Su maestro la acepta o la rechaza."] = "Il capogilda la crea e invita qualcuno di un'altra gilda che abbia BlazonGuild. Il loro capogilda accetta o rifiuta.",
  ["El maestro nombra a los capitanes (leen y escriben en «Oficiales de la alianza») y a los mensajeros (llevan los mensajes a las otras hermandades)."] = "Il maestro nomina i capitani (leggono e scrivono in «Ufficiali dell'alleanza») e i messaggeri (portano i messaggi alle altre gilde).",
  ["El maestro nombra a los tesoreros en «Cuotas». Son quienes guardan el oro de la hermandad. El addon nunca mueve oro: solo lo apunta."] = "Il capogilda nomina i tesorieri in «Quote». Sono loro a custodire l'oro della gilda. L'addon non sposta mai oro: lo annota soltanto.",
  ["El maestro pulsa «Publicar nuestras cifras» en Rankings, pestaña «Hermandades». Se ven al jugar en grupo con alguien de otra hermandad que use BlazonGuild. Solo cifras de la hermandad, nada de nadie en concreto."] = "Il capogilda preme «Pubblica i nostri numeri» in Classifiche, scheda «Gilde». Si vedono giocando in gruppo con qualcuno di un'altra gilda che usa BlazonGuild. Solo numeri della gilda, niente di nessuno in particolare.",
  ["El maestro%s invita a otras hermandades y decide si seguís en la alianza."] = "Il capogilda%s invita altre gilde e decide se restate nell'alleanza.",
  ["El mes de la hermandad: raids y eventos de BlazonGuild junto a los del calendario del juego."] = "Il mese della gilda: incursioni ed eventi di BlazonGuild accanto a quelli del calendario del gioco.",
  ["El modo capturas ha terminado: vuelves a ver tu hermandad."] = "La modalità screenshot è terminata: torni a vedere la tua gilda.",
  ["El parte"] = "Il rapporto",
  ["El primero de cada ranking lleva ese honor: sale en su ficha, con un escudo dorado sobre su nombre en el juego y junto a lo que escribe en el chat."] = "Il primo di ogni classifica porta quell'onore: compare nella sua scheda, con uno stemma dorato sopra il suo nome nel gioco e accanto a ciò che scrive in chat.",
  ["El primero de cada ranking lleva su honor: sale en su ficha, con un escudo dorado sobre su nombre y en el chat."] = "Il primo di ogni classifica porta il suo onore: compare nella sua scheda, con uno stemma dorato sopra il suo nome e in chat.",
  ["El punto del minimapa y la flecha ya no gastan nada mientras no hay nada que dibujar."] = "I punti della minimappa e la freccia non costano nulla finché non c'è niente da disegnare.",
  ["El tesorero"] = "Il tesoriere",
  ["El texto ya nunca queda debajo de los botones de la tarjeta."] = "Il testo non resta mai più sotto i pulsanti della scheda.",
  ["Elegir a quién…"] = "Scegli chi…",
  ["Elegir…"] = "Scegli…",
  ["Elige a alguien de tu hermandad."] = "Scegli qualcuno della tua gilda.",
  ["Elige a cada luchador de la lista (los miembros, por orden alfabético), o escribe parte de su nombre y la lista se queda solo con los que coinciden."] = "Scegli ogni combattente dalla lista (i membri, in ordine alfabetico), o scrivi parte del suo nome e la lista tiene solo quelli che corrispondono.",
  ["Elige a dos luchadores distintos."] = "Scegli due combattenti diversi.",
  ["Elige a quién retar"] = "Scegli chi sfidare",
  ["Elige el día y la hora."] = "Scegli il giorno e l'ora.",
  ["Elige la banda, el día y la hora."] = "Scegli l'incursione, il giorno e l'ora.",
  ["Elige la banda, el día y la hora. Tu hermandad la verá al instante y se apuntará desde el juego con su rol."] = "Scegli l'incursione, il giorno e l'ora. La tua gilda la vedrà subito e si iscriverà dal gioco con il suo ruolo.",
  ["Elige para qué es el grupo: una mazmorra, una banda u otra actividad."] = "Scegli a cosa serve il gruppo: un'istanza, un'incursione o un'altra attività.",
  ["Elige uno a la izquierda, o crea uno con «Nuevo»."] = "Scegline uno a sinistra, o creane uno con «Nuovo».",
  ["Empate"] = "Pareggio",
  ["Empezar"] = "Inizia",
  ["Empezar la temporada %s"] = "Inizia la stagione %s",
  ["Empezar la velada"] = "Inizia la serata",
  ["Empiezas tú: pulsa «Tirar» en la Taberna."] = "Inizi tu: premi «Tira» nella Taverna.",
  ["En %s. "] = "A %s. ",
  ["En Artesanía y botín: busca el objeto y susurra al artesano o hazle un encargo. Los artesanos publican su profesión al abrirla en el juego."] = "In Artigianato e bottino: cerca l'oggetto e sussurra all'artigiano o fagli un ordine. Gli artigiani pubblicano la loro professione aprendola nel gioco.",
  ["En Mapa, pestaña «Avistamientos», preguntas dónde se vio a un jugador de la otra facción. Responden los compañeros que lo aceptan, con lo que vieron en el último cuarto de hora. Nada se envía si nadie pregunta."] = "In Mappa, scheda «Avvistamenti», chiedi dove è stato visto un giocatore dell'altra fazione. Rispondono i compagni che lo accettano, con ciò che hanno visto nell'ultimo quarto d'ora. Non si invia nulla se nessuno chiede.",
  ["En Mapa, pestaña «En el mapa», pulsa «Seguir» junto a su nombre: una flecha bajo el minimapa te lleva hasta él. Sirve con quien comparte su posición y con el punto de reunión."] = "In Mappa, scheda «Sulla mappa», premi «Segui» accanto al suo nome: una freccia sotto la minimappa ti porta da lui. Funziona con chi condivide la posizione e con il punto di ritrovo.",
  ["En cola"] = "In coda",
  ["En curso"] = "In corso",
  ["En el chat, una pestaña para toda la alianza y otra para cada hermandad hermana; las salas de roles se comparten."] = "In chat, una scheda per tutta l'alleanza e un'altra per ogni gilda sorella; le stanze dei ruoli sono condivise.",
  ["En el de tu juego: español, inglés, alemán, francés, italiano, portugués o ruso. Para otro, en Administración, «Idioma del addon», o escribe /bg idioma en. Se aplica al recargar la interfaz."] = "In quella del tuo gioco: spagnolo, inglese, tedesco, francese, italiano, portoghese o russo. Per un'altra, vai in Amministrazione, «Lingua dell'addon», o scrivi /bg idioma it. Si applica ricaricando l'interfaccia.",
  ["En el juego, abre la ventana de tu profesión (por ejemplo, Herrería). BlazonGuild te pregunta si quieres que tu hermandad lo vea: di «Publicar»."] = "Nel gioco, apri la finestra della tua professione (per esempio Forgiatura). BlazonGuild ti chiede se vuoi che la tua gilda la veda: di' «Pubblica».",
  ["En el mapa"] = "Sulla mappa",
  ["En el modo capturas no se hace nada en el juego: es solo una hermandad de ejemplo."] = "In modalità screenshot non si fa nulla nel gioco: è solo una gilda di esempio.",
  ["En el nivel máximo"] = "Al livello massimo",
  ["En inglés y los demás idiomas: los títulos del Tablón y el Calendario, el oro de la Tesorería, la Arena, los grupos y la Sala de guerra ya salen traducidos."] = "In inglese e nelle altre lingue: i titoli della Bacheca e del Calendario, l'oro della Tesoreria, l'Arena, i gruppi e la Sala di guerra ora sono tradotti.",
  ["En juego"] = "In gioco",
  ["En juego, %s luchadores. Cada combate lo decide el primer duelo entre los dos."] = "In gioco, %s combattenti. Ogni combattimento lo decide il primo duello tra i due.",
  ["En juego: cada combate lo decide el primer duelo entre los dos."] = "In gioco: ogni combattimento lo decide il primo duello tra i due.",
  ["En la Arena, pestaña «Taberna». Tiras seis dados, apartas los que puntúan (unos, cincos, tríos…) y decides si sigues o te plantas. Si una tirada no da nada, pierdes lo del turno. Gana quien llega a 3000."] = "Nell'Arena, scheda «Taverna». Tiri sei dadi, metti da parte quelli che fanno punti (uno, cinque, tris…) e decidi se continuare o fermarti. Se un tiro non dà niente, perdi i punti del turno. Vince chi arriva a 3000.",
  ["En la Arena, pestaña «Torneos», pulsa «Nuevo». La gente se apunta; tú pulsas «Sortear y empezar» y sale el cuadro. Cada combate lo decide su duelo."] = "Nell'Arena, scheda «Tornei», premi «Nuovo». La gente si iscrive; tu premi «Sorteggia e inizia» ed esce il tabellone. Ogni combattimento lo decide il suo duello.",
  ["En la Arena: %s."] = "Nell'Arena: %s.",
  ["En la Arena: %s. "] = "Nell'Arena: %s. ",
  ["En la Armería de BlazonGuild. Si dices que sí, compartes con tu hermandad lo que llevas puesto (lo mismo que ve quien te inspecciona en el juego), y se pone al día cuando te cambias."] = "Nell'Armeria di BlazonGuild. Se dici di sì, condividi con la tua gilda cosa indossi (come chi ti ispeziona nel gioco), e si aggiorna quando ti cambi.",
  ["En la app"] = "Nell'app",
  ["En la final contra %s. Enhorabuena al campeón."] = "In finale contro %s. Complimenti al campione.",
  ["En la hermandad"] = "Nella gilda",
  ["En la pestaña «En el mapa», «Seguir» pone una flecha bajo el minimapa que te lleva hasta un compañero o hasta el punto de reunión, con los metros que faltan."] = "Nella scheda «Sulla mappa», «Segui» mette sotto la minimappa una freccia che ti porta da un compagno o al punto di ritrovo, con la distanza che manca.",
  ["En la pestaña «Quién fabrica qué», escribe el objeto (por ejemplo «poción») y verás quién sabe hacerlo. «Susurrar» abre el chat para hablarle."] = "Nella scheda «Chi fabbrica cosa», scrivi l'oggetto (per esempio «pozione») e vedrai chi sa farlo. «Sussurra» apre la chat per parlargli.",
  ["En la próxima entrega del addon"] = "Nella prossima versione dell'addon",
  ["En la raid, pulsa «Grupos» y arrastra a cada uno a su grupo. Cuando la banda esté formada en el juego, «Colocar en la banda» los mueve de verdad."] = "Nell'incursione, premi «Gruppi» e trascina ognuno nel suo gruppo. Quando l'incursione sarà formata nel gioco, «Colloca nell'incursione» li sposterà davvero.",
  ["En la sección Chat aparecen las pestañas de la alianza: «Toda la alianza» y una por cada hermandad hermana."] = "Nella sezione Chat compaiono le schede dell'alleanza: «Tutta l'alleanza» e una per ogni gilda sorella.",
