  ["En marcha: "] = "In corso: ",
  ["En marcha: %s, %s."] = "In corso: %s, %s.",
  ["En vivo"] = "Dal vivo",
  ["En vivo, hace %d s"] = "Dal vivo, %d s fa",
  ["En «Avistamientos» preguntas dónde se vio a un jugador de la otra facción. Responden los compañeros que lo aceptan, con lo que vieron en el último cuarto de hora."] = "In «Avvistamenti» chiedi dove è stato visto un giocatore dell'altra fazione. Rispondono i compagni che lo accettano, con ciò che hanno visto nell'ultimo quarto d'ora.",
  ["En «Encargos», pide el objeto. El artesano pulsa «Lo hago» y luego «Hecho»; cuando lo tengas, pulsa «Recibido». Te avisamos en cada paso."] = "In «Ordini», chiedi l'oggetto. L'artigiano preme «Lo faccio» e poi «Fatto»; quando ce l'hai, premi «Ricevuto». Ti avvisiamo a ogni passo.",
  ["En «Retos» retas a quien esté conectado; si acepta, os avisamos. «Cara a cara» pone a dos luchadores frente a frente, con su vida en directo si están cerca. Sin oro."] = "In «Sfide» sfidi chi è connesso; se accetta, vi avvisiamo entrambi. «Faccia a faccia» mette due combattenti uno di fronte all'altro, con la vita in diretta se sono vicini. Senza oro.",
  ["En «Retos» ves quién está conectado y puedes retarle. Si acepta, os avisamos a los dos. Aquí no se apuesta oro."] = "In «Sfide» vedi chi è connesso e puoi sfidarlo. Se accetta, avvisiamo entrambi. Qui non si scommette oro.",
  ["En «Torneos», cualquiera crea uno. Cada uno se apunta; quien lo dirige sortea con /roll y sale el cuadro. Cada combate lo decide el duelo entre los dos."] = "In «Tornei», chiunque ne crea uno. Ognuno si iscrive; chi lo dirige sorteggia con /roll ed esce il tabellone. Ogni combattimento lo decide il duello tra i due.",
