  ["La hermandad no sale: pulsa para publicar sus cifras (nada de nadie en concreto). "] = "La gilda non compare: premi per pubblicare i suoi numeri (niente di nessuno in particolare). ",
  ["La hermandad que lidera escribe cartas a los maestros, dice a qué hermandad van los nuevos y puede ocultar a alguien en los chats comunes. Y en la Sala de guerra, sus operaciones llegan a todas."] = "La gilda che guida scrive lettere ai maestri, dice a quale gilda vanno i nuovi e può nascondere qualcuno nelle chat comuni. E nella sala di guerra, le sue operazioni arrivano a tutte.",
  ["La hermandad que lidera la alianza planea la operación en su Sala de guerra eligiendo «Toda la alianza». Llega a la Sala de guerra de cada hermandad; cada uno responde allí y el líder ve cuántos van de cada una."] = "La gilda che guida l'alleanza pianifica l'operazione nella sua sala di guerra scegliendo «Tutta l'alleanza». Arriva alla sala di guerra di ogni gilda; ognuno risponde lì e il capo vede quanti vanno da ciascuna.",
  ["La línea de BlazonGuild en el recuadro de un jugador"] = "La riga di BlazonGuild nel riquadro di un giocatore",
  ["La mejor puntuación de la Arena de la hermandad."] = "Il miglior punteggio dell'Arena della gilda.",
  ["La mejor puntuación de la Arena esta temporada, con 5 combates o más."] = "Il miglior punteggio dell'Arena in questa stagione, con 5 combattimenti o più.",
  ["La prueba no ha vuelto"] = "La prova non è tornata",
  ["La puntuación"] = "Il punteggio",
  ["La sala de este evento de la Arena, para quien lucha y quien mira. Se cierra una semana después de crearlo."] = "La stanza di questo evento dell'Arena, per chi combatte e chi guarda. Si chiude una settimana dopo la creazione.",
  ["La semana pasada: "] = "La settimana scorsa: ",
  ["La temporada %s se cierra y se guarda con su campeón y su podio."] = "La stagione %s si chiude e si salva con il suo campione e il suo podio.",
  ["La ventana de BlazonGuild, sus diálogos y sus avisos"] = "La finestra di BlazonGuild, i suoi dialoghi e i suoi avvisi",
  ["La ventana «Cara a cara»"] = "La finestra «Faccia a faccia»",
  ["Las Mazmorras"] = "Le Segrete",
  ["Las Minas de la Muerte"] = "Le Miniere della Morte",
  ["Las capas"] = "I layer",
  ["Las cartas del líder de la alianza son para los maestros y los capitanes de cada hermandad."] = "Le lettere del capo dell'alleanza sono per i maestri e i capitani di ogni gilda.",
  ["Las decisiones finales de moderación siguen siendo del maestro."] = "Le decisioni finali di moderazione restano del capogilda.",
  ["Las demás hermandades ya lo saben."] = "Le altre gilde lo sanno già.",
  ["Las hermandades de vuestra facción que juegan con BlazonGuild y publican sus cifras. Se conocen al jugar en grupo con alguien de ellas."] = "Le gilde della vostra fazione che giocano con BlazonGuild e pubblicano i loro numeri. Si conoscono giocando in gruppo con qualcuno di loro.",
  ["Las hermandades la reciben solas; durante un minuto puede perderse algún mensaje."] = "Le gilde la ricevono da sole; per un minuto qualche messaggio può perdersi.",
  ["Las inscripciones ya están cerradas."] = "Le iscrizioni sono già chiuse.",
  ["Las listas para elegir a alguien ya no salen vacías: se hacen al abrirlas, y si no hay nadie lo dicen."] = "Gli elenchi per scegliere qualcuno non si aprono più vuoti: si creano all'apertura, e se non c'è nessuno lo dicono.",
  ["Las marcas"] = "I segni",
  ["Las marcas sobre las placas de nombre y el aro del retrato del objetivo"] = "I segni sulle targhette e l'anello sul ritratto del bersaglio",
  ["Las mazmorras de dentro de una capital son de su bando; las demás, para todos (las Minas de la Muerte y el Castillo de Colmillo Oscuro ya salen a las dos facciones)."] = "I dungeon dentro una capitale sono della sua fazione; gli altri sono per tutti (Le Miniere della Morte e la Rocca di Zannascura ora compaiono per entrambe le fazioni).",
  ["Las mazmorras y bandas son ya las de WoW Forever: sus 9 mazmorras nuevas (Salón de los Feudales, Ruinas de Lordaeron, Ciudad de Dalaran, Bastión Faucenegra…) y sus tres bandas, Cavernas del Túmulo, Cima Hyjal y Guarida de Onyxia, con los nombres del juego."] = "Dungeon e incursioni ora sono quelli di WoW Forever: i suoi 9 nuovi dungeon (Hall of Thanes, Rovine di Lordaeron, City of Dalaran, Blackmaw Hold…) e le sue tre incursioni, The Barrow Deeps, Hyjal Summit e Covo di Onyxia, con i nomi del gioco.",
  ["Las otras hermandades aún no han dicho cuántos van."] = "Le altre gilde non hanno ancora detto quanti vanno.",
  ["Las otras hermandades no te verán conectado. Los mensajes de «Maestros» de otras hermandades no te llegarán mientras sigas oculto."] = "Le altre gilde non ti vedranno connesso. I messaggi «Capigilda» delle altre gilde non ti arriveranno finché resti nascosto.",
  ["Las otras hermandades vuelven a verte conectado."] = "Le altre gilde ti vedono di nuovo connesso.",
  ["Las próximas dos semanas"] = "Le prossime due settimane",
  ["Las próximas dos semanas (%s)"] = "Le prossime due settimane (%s)",
  ["Las raids se comparten entre los addons de tu hermandad. Para crearlas, verlas y apuntarte, acepta antes la privacidad."] = "Le incursioni si condividono tra gli addon della tua gilda. Per crearle, vederle e iscriverti, accetta prima la privacy.",
  ["Las salas de roles y el comercio se comparten con todas."] = "Le stanze dei ruoli e il commercio sono condivisi con tutte.",
  ["Le hemos preguntado si lo comparte; esperando su respuesta."] = "Gli abbiamo chiesto se lo condivide; in attesa della risposta.",
  ["Le toca a %s%s"] = "Tocca a %s%s",
  ["Le toca a %s…"] = "Tocca a %s…",
  ["Levantar bandera"] = "Alza bandiera",
  ["Libro"] = "Registro",
  ["Libro de la tesorería"] = "Registro della tesoreria",
  ["Libro para todos: %s"] = "Registro per tutti: %s",
  ["Liderazgo"] = "Comando",
  ["Llamada a los oficiales"] = "Chiamata agli ufficiali",
  ["Llamar a los oficiales"] = "Chiama gli ufficiali",
  ["Llegó a través de %s. «Invitar» manda la invitación del juego; «No» se lo dice con educación."] = "È arrivata tramite %s. «Invita» manda l'invito del gioco; «No» glielo dice con garbo.",
  ["Lleva un tabardo."] = "Indossa una tabarda.",
  ["Lo apuntó el addon de %s, que perdió: solo quien pierde apunta el combate, para que nadie se dé victorias."] = "L'ha annotato l'addon di %s, che ha perso: solo chi perde annota il combattimento, perché nessuno si dia vittorie.",
  ["Lo comparte él mismo (%s)."] = "Lo condivide lui stesso (%s).",
  ["Lo comparte: ya lo ves aunque esté lejos."] = "Lo condivide: lo vedi anche se è lontano.",
  ["Lo comparten al momento quienes tienen el addon; del resto llega desde la web a través de la app puente."] = "Lo condividono subito quelli che hanno l'addon; per il resto arriva dal web tramite l'app ponte.",
  ["Lo comparten los miembros con el addon; del resto, Battle.net a través de la web."] = "Lo condividono i membri con l'addon; per il resto, Battle.net tramite il web.",
  ["Lo decide el maestro. Ahora: %s"] = "Lo decide il capogilda. Ora: %s",
  ["Lo decide su primer duelo: clic derecho en el retrato del otro, «Duelo»."] = "Lo decide il loro primo duello: clic destro sul ritratto dell'altro, «Duello».",
  ["Lo hace %s."] = "Lo fa %s.",
  ["Lo hago"] = "Lo faccio io",
  ["Lo lleva %s"] = "Lo porta %s",
  ["Lo pide %s. %s%s"] = "Lo chiede %s. %s%s",
  ["Lo puedes cambiar cuando quieras en la Armería."] = "Puoi cambiarlo quando vuoi nell'Armeria.",
  ["Lo puedes quitar cuando quieras en la Armería («Compartir mi equipo»)."] = "Puoi toglierlo quando vuoi nell'Armeria («Condividi il mio equipaggiamento»).",
  ["Lo que dice cualquiera en el chat de hermandad, tenga o no el addon. Lo que se dijo mientras no estabas te lo pasa un compañero con BlazonGuild."] = "Ciò che dice chiunque nella chat di gilda, con o senza addon. Quello che si è detto mentre non c'eri te lo passa un compagno con BlazonGuild.",
  ["Lo que el propio juego dice de ti y cuenta para la hermandad: tus duelos con compañeros, quién te mata en JcJ fuera de mazmorras, el oro que das a un tesorero y los jefes que matáis juntos."] = "Ciò che il gioco stesso dice di te e che conta per la gilda: i tuoi duelli con i compagni, chi ti uccide in PvP fuori dai dungeon, l'oro che dai a un tesoriere e i boss che uccidete insieme.",
  ["Lo que la hermandad debe saber"] = "Ciò che la gilda deve sapere",
  ["Lo que publicas lo ve tu hermandad: quién sabe hacer cada objeto, para susurrarte o hacerte un encargo. Se actualiza al abrir la profesión."] = "Ciò che pubblichi lo vede la tua gilda: chi sa fare ogni oggetto, per sussurrarti o farti un ordine. Si aggiorna aprendo la professione.",
  ["Lo que responde aquí"] = "Cosa risponde qui",
  ["Lo que tu hermandad publique desde el juego podrá verse también en la web de BlazonGuild."] = "Ciò che la tua gilda pubblica dal gioco si potrà vedere anche sul sito di BlazonGuild.",
  ["Lo que tú hagas desde el addon: apuntarte a una raid, publicar un grupo, tu perfil… Cada cosa la decides tú en el momento."] = "Ciò che fai dall'addon: iscriverti a un'incursione, pubblicare un gruppo, il tuo profilo… Ogni cosa la decidi tu sul momento.",
  ["Lo verás en la Armería en un momento."] = "Lo vedrai nell'Armeria tra un momento.",
  ["Lo verás todo en /bg."] = "Vedrai tutto in /bg.",
  ["Lo vio el propio cliente de %s (el resumen de muerte del juego)."] = "L'ha visto il client stesso di %s (il riepilogo di morte del gioco).",
  ["Lo viste tú (%s)."] = "L'hai visto tu (%s).",
  ["Lo último"] = "Le ultime",
  ["Lo último: %s"] = "Ultimo: %s",
  ["Logros"] = "Imprese",
  ["Los Baldíos"] = "Le Savane",
  ["Los Humedales"] = "Wetlands",
  ["Los apuntados la verán como cancelada. Se puede volver a programar editándola."] = "Gli iscritti la vedranno annullata. Si può riprogrammare modificandola.",
  ["Los cambios de la alianza van firmados: nadie puede falsificarlos."] = "Le modifiche dell'alleanza sono firmate: nessuno può falsificarle.",
  ["Los capitanes leen y escriben en «Oficiales de la alianza»; los mensajeros llevan los mensajes a las otras hermandades. Escribe su nombre y elige el cargo."] = "I capitani leggono e scrivono in «Ufficiali dell'alleanza»; i messaggeri portano i messaggi alle altre gilde. Scrivi il nome e scegli l'incarico.",
  ["Los casos de moderación y los avisos ya solo están en el ordenador de los organizadores."] = "I casi di moderazione e gli avvisi ora sono solo sul computer degli organizzatori.",
  ["Los combates de antes siguen guardados, pero ya no cuentan."] = "I combattimenti precedenti restano salvati, ma non contano più.",
  ["Los conectados de cada zona, tengan o no BlazonGuild."] = "I connessi di ogni zona, con o senza BlazonGuild.",
  ["Los enlaces de objetos del chat se ven bien (antes salían rotos), también los ya guardados."] = "I link degli oggetti in chat si vedono bene (prima erano rotti), anche quelli già salvati.",
  ["Los grupos"] = "I gruppi",
  ["Los grupos se comparten entre los addons de tu hermandad. Acepta la privacidad para verlos (/bg privacidad)."] = "I gruppi si condividono tra gli addon della tua gilda. Accetta la privacy per vederli (/bg privacidad).",
  ["Los jefes de las bandas se apuntan aunque el juego dé solo el nombre, y la clasificación de hermandades ya verifica las fichas de las demás."] = "I boss delle incursioni si registrano anche quando il gioco dà solo il nome, e la classifica delle gilde ora verifica le schede delle altre.",
  ["Los mueven el líder de la raid, quien la creó y los oficiales. Tú lo ves tal como está."] = "Li spostano il leader dell'incursione, chi l'ha creata e gli ufficiali. Tu lo vedi così com'è.",
  ["Los nombres y lo que escribe cada uno (notas, anuncios, mensajes) salen tal cual, sin traducir."] = "I nomi e ciò che scrive ognuno (note, annunci, messaggi) appaiono così come sono, senza traduzione.",
  ["Los oficiales apuntan a quién se dio cada objeto y por qué, para que la próxima banda empiece de lo ya decidido. Sin pujas ni oro."] = "Gli ufficiali annotano a chi è andato ogni oggetto e perché, così la prossima incursione parte da quanto già deciso. Senza offerte né oro.",
  ["Los oficiales crean escuadras pequeñas con su jefe (por ejemplo «Los Lobos», de asalto). El jefe elige a su gente; la escuadra tiene su propio chat."] = "Gli ufficiali creano piccole squadre con il loro capo (per esempio «I Lupi», d'assalto). Il capo sceglie la sua gente; la squadra ha la sua chat.",
  ["Los oficiales de %s ya la ven. Te invitarán desde el juego si dicen que sí."] = "Gli ufficiali di %s la vedono già. Ti inviteranno dal gioco se dicono di sì.",
  ["Los oficiales escriben la ficha pública: a qué os dedicáis, idioma, cuándo jugáis y a quién buscáis (por ejemplo, sanadores)."] = "Gli ufficiali scrivono la scheda pubblica: di cosa vi occupate, lingua, quando giocate e chi cercate (per esempio, guaritori).",
  ["Los organizadores de todas las hermandades de la alianza. Nadie más lo lee."] = "Gli organizzatori di tutte le gilde dell'alleanza. Nessun altro la legge.",
  ["Los organizadores nombran árbitros en la Arena. Un árbitro puede decidir a mano los combates de cualquier torneo y quitar un duelo apuntado por error."] = "Gli organizzatori nominano arbitri nell'Arena. Un arbitro può decidere a mano gli incontri di qualsiasi torneo e togliere un duello registrato per errore.",
  ["Los organizadores pueden ver el addon como un miembro («Ver como miembro»), y otros addons pueden leer BlazonGuild si tú les das permiso."] = "Gli organizzatori possono vedere l'addon come un membro («Vedi come membro»), e altri addon possono leggere BlazonGuild se lo permetti.",
  ["Los puntos de los compañeros en el mapa del mundo"] = "I punti dei compagni sulla mappa del mondo",
  ["Los puntos del minimapa y la flecha «Seguir»"] = "I punti della minimappa e la freccia «Segui»",
  ["Los que guardas valen %d."] = "Quelli che tieni valgono %d.",
