  ["Lugar: «%s»"] = "Luogo: «%s»",
  ["Líder: %s, maestro de %s."] = "Leader: %s, capogilda di %s.",
  ["Maestro: %s. Aún sin contacto: llegará cuando se conecte alguien suyo con BlazonGuild."] = "Capogilda: %s. Ancora senza contatto: arriverà quando si connetterà qualcuno dei loro con BlazonGuild.",
  ["Maestros"] = "Capigilda",
  ["Mago"] = "Mago",
  ["Mano derecha"] = "Mano primaria",
  ["Mano izquierda"] = "Mano secondaria",
  ["Manos"] = "Mani",
  ["Mapa"] = "Mappa",
  ["Mapa explica qué pasa al compartir tu posición, quién te ve y dónde, y abre el mapa del mundo."] = "Mappa spiega cosa succede condividendo la tua posizione, chi ti vede e dove, e apre la mappa del mondo.",
  ["Mapa, pestaña «Avistamientos»: pregunta a tu hermandad dónde se vio a un jugador de la otra facción (responde quien lo acepta)."] = "Mappa, scheda «Avvistamenti»: chiedi alla tua gilda dove è stato visto un giocatore dell'altra fazione (risponde chi lo accetta).",
  ["Mapa, pestaña «En el mapa»: «Seguir» pone una flecha bajo el minimapa que te lleva hasta un compañero o hasta el punto de reunión."] = "Mappa, scheda «Sulla mappa»: «Segui» mette sotto la minimappa una freccia che ti porta da un compagno o al punto di ritrovo.",
  ["Mapa: quien comparte su posición sale ahora también como un punto en tu minimapa."] = "Mappa: chi condivide la posizione ora appare anche come un punto sulla tua minimappa.",
  ["Maraudon"] = "Maraudon",
  ["Marcar leída"] = "Segna come letta",
  ["Marcas en el chat del juego"] = "Segni nella chat del gioco",
  ["Marcas en nombres y chat: no"] = "Segni su nomi e chat: no",
  ["Marcas en nombres y chat: sí"] = "Segni su nomi e chat: sì",
  ["Marjal Revolcafango"] = "Dustwallow Marsh",
