  ["Mi ficha"] = "La mia scheda",
  ["Miembros"] = "Membri",
  ["Miembros con el addon conectados hace poco."] = "Membri con l'addon connessi di recente.",
  ["Miembros en el nivel máximo."] = "Membri al livello massimo.",
  ["Miembros nuevos que dicen que los trajo (180 días)."] = "Nuovi membri che dicono che li ha portati lui (180 giorni).",
  ["Miembros que publican sus profesiones."] = "Membri che pubblicano le loro professioni.",
  ["Miembros que se han conectado en los últimos 7 días."] = "Membri che si sono connessi negli ultimi 7 giorni.",
  ["Miembros: %s (jefe)%s."] = "Membri: %s (capo)%s.",
  ["Mientras tanto ya funcionan en vivo: Resumen, La hermandad, Raids, Mazmorras y Calendario."] = "Nel frattempo funzionano già dal vivo: Riepilogo, La gilda, Incursioni, Istanze e Calendario.",
  ["Minas de la Muerte"] = "Le Miniere della Morte",
