  ["Moderación"] = "Moderazione",
  ["Moderación para los organizadores, con avisos y casos que decide el maestro."] = "Moderazione per gli organizzatori, con avvisi e casi che decide il capogilda.",
  ["Moderar"] = "Modera",
  ["Moderar a %s"] = "Modera %s",
  ["Modo capturas"] = "Modalità screenshot",
  ["Modo capturas (/bg capturas, o «Capturas» en Administración): una hermandad de ejemplo con nombres inventados, solo en tu pantalla, para enseñar BlazonGuild con todas las pantallas llenas. No sale nada de tu juego."] = "Modalità screenshot (/bg capturas, o «Screenshot» in Amministrazione): una gilda di esempio con nomi inventati, solo sul tuo schermo, per mostrare BlazonGuild con tutte le schermate piene. Niente esce dal tuo gioco.",
  ["Modo capturas: una hermandad de ejemplo"] = "Modalità screenshot: una gilda di esempio",
  ["Modo mando"] = "Modalità controller",
  ["Monasterio Escarlata"] = "Monastero Scarlatto",
  ["Montaña Roca Negra"] = "Montagna Roccianera",
  ["Montañas de Alterac"] = "Montagne di Alterac",
  ["Monte Hyjal"] = "Monte Hyjal",
  ["Mostrar a tu hermandad qué personajes son tuyos"] = "Mostra alla tua gilda quali personaggi sono tuoi",
  ["Mostrarlos"] = "Mostrali",
  ["Mostrarme conectado"] = "Mostrami connesso",
  ["Muertes con honor y actividad JcJ de cada miembro y por clase."] = "Uccisioni onorevoli e attività PvP di ogni membro e per classe.",
  ["Muertes que ha causado: %s%s. Última víctima: %s."] = "Morti che ha causato: %s%s. Ultima vittima: %s.",
  ["Muñecas"] = "Polsi",
  ["Más tarde"] = "Più tardi",
  ["Nada"] = "Niente",
  ["Nada en las próximas dos semanas: ni raids de BlazonGuild ni eventos en el calendario del juego. Las raids que cree cualquier miembro en Raids aparecerán aquí."] = "Niente nelle prossime due settimane: né incursioni di BlazonGuild né eventi nel calendario del gioco. Le incursioni create da qualsiasi membro in Incursioni appariranno qui.",
  ["Nadie"] = "Nessuno",
  ["Nadie (acepta la privacidad para aparecer)"] = "Nessuno (accetta la privacy per apparire)",
  ["Nadie ahora. Las peticiones las ven los oficiales."] = "Nessuno ora. Le richieste le vedono gli ufficiali.",
  ["Nadie ahora. Las peticiones llegan mientras estás conectado; «Invitar» manda la invitación del juego."] = "Nessuno ora. Le richieste arrivano mentre sei connesso; «Invita» manda l'invito del gioco.",
  ["Nadie coincide con la búsqueda."] = "Nessuno corrisponde alla ricerca.",
  ["Nadie comparte ahora su posición. Cada uno lo enciende con «Compartir mi posición»."] = "Nessuno condivide la posizione ora. Ognuno la attiva con «Condividi la mia posizione».",
  ["Nadie con recompensa. Cuando alguien de la otra facción mate a un miembro fuera de mazmorras, aparecerá aquí por sí solo."] = "Nessuno con taglia. Quando qualcuno dell'altra fazione ucciderà un membro fuori dalle istanze, apparirà qui da solo.",
  ["Nadie conectado ahora mismo."] = "Nessuno connesso in questo momento.",
  ["Nadie de la hermandad se llama así. Borra lo escrito para ver a todos."] = "Nessuno della gilda si chiama così. Cancella ciò che hai scritto per vedere tutti.",
  ["Nadie de la lista sabe hacer «%s». En «Encargos» puedes pedirlo a quien sepa."] = "Nessuno della lista sa fare «%s». In «Ordini» puoi chiederlo a chi sa farlo.",
  ["Nadie de «%s» conectado ahora, o el nombre no es exacto."] = "Nessuno di «%s» connesso ora, o il nome non è esatto.",
  ["Nadie elegido"] = "Nessuno scelto",
  ["Nadie en la hermandad."] = "Nessuno nella gilda.",
  ["Nadie en reserva."] = "Nessuno in riserva.",
  ["Nadie ha escrito aquí todavía. Empieza tú: lo leerán con BlazonGuild las hermandades de este canal."] = "Nessuno ha ancora scritto qui. Comincia tu: lo leggeranno con BlazonGuild le gilde di questo canale.",
  ["Nadie ha escrito aquí todavía. Empieza tú: lo leerán los miembros con BlazonGuild."] = "Nessuno ha ancora scritto qui. Comincia tu: lo leggeranno i membri con BlazonGuild.",
  ["Nadie ha levantado bandera. Levanta la tuya arriba y la hermandad sabrá que buscas grupo."] = "Nessuno ha alzato bandiera. Alza la tua qui sopra e la gilda saprà che cerchi gruppo.",
  ["Nadie lo ha visto todavía."] = "Nessuno l'ha ancora visto.",
  ["Nadie lo tenía."] = "Nessuno lo aveva.",
  ["Nadie lo tenía. Mañana, más boletos gratis."] = "Nessuno lo aveva. Domani, altri biglietti gratis.",
  ["Nadie más conectado ahora mismo."] = "Nessun altro connesso in questo momento.",
  ["Nadie más de la hermandad está conectado ahora."] = "Nessun altro della gilda è connesso ora.",
  ["Nadie más está conectado ahora."] = "Nessun altro è connesso ora.",
  ["Nadie te ha retado ahora. Cuando alguien lo haga, te sale aquí con «Aceptar» y «No».\n\nCómo se reta: pulsa «Retar» junto a alguien de la lista (tiene que estar conectado y con BlazonGuild). Si acepta, os avisamos a los dos.\n\nEl duelo lo empezáis desde el juego (clic derecho en su retrato, «Duelo»). Retar no es obligatorio: cualquier duelo entre dos de la hermandad con BlazonGuild cuenta."] = "Nessuno ti ha sfidato ora. Quando qualcuno lo farà, apparirà qui con «Accetta» e «No».\n\nCome si sfida: premi «Sfida» accanto a qualcuno della lista (deve essere connesso e avere BlazonGuild). Se accetta, avvisiamo entrambi.\n\nIl duello lo iniziate dal gioco (clic destro sul suo ritratto, «Duello»). Sfidare non è obbligatorio: qualsiasi duello tra due della gilda con BlazonGuild conta.",
  ["Nadie tiene puntos apuntados."] = "Nessuno ha punti annotati.",
  ["Nadie todavía"] = "Ancora nessuno",
  ["Nadie. El líder puede ocultar a un jugador o a una hermandad en los chats comunes durante un tiempo."] = "Nessuno. Il capo può nascondere un giocatore o una gilda nelle chat comuni per un po'.",
  ["Naxxramas"] = "Naxxramas",
  ["Necesitas estar en una hermandad."] = "Devi essere in una gilda.",
  ["Ninguna"] = "Nessuna",
  ["Ninguna encuesta abierta. Cualquiera puede preguntar a la hermandad: qué banda hacer, a qué hora quedar…"] = "Nessun sondaggio aperto. Chiunque può chiedere alla gilda: che incursione fare, a che ora trovarsi…",
  ["Ninguna. Cuando otra hermandad os invite, aparecerá aquí y vuestro maestro decidirá."] = "Nessuna. Quando un'altra gilda vi inviterà, apparirà qui e il vostro capogilda deciderà.",
  ["Ninguno"] = "Nessuno",
  ["Ninguno en esta versión"] = "Nessuno in questa versione",
  ["Ningún botón se sale de su panel: ahora lo comprueban las pruebas en todas las pantallas."] = "Nessun pulsante esce dal suo pannello: ora lo controllano i test in tutte le schermate.",
  ["Ningún organizador con BlazonGuild está conectado ahora. Prueba más tarde."] = "Nessun organizzatore con BlazonGuild è connesso ora. Riprova più tardi.",
