  ["Nivel y logros en vivo del juego; equipo y JcJ, de los miembros con el addon y de la web."] = "Livello e imprese dal vivo dal gioco; equipaggiamento e PvP, dai membri con l'addon e dal web.",
  ["Niveles en vivo del juego y raids de BlazonGuild."] = "Livelli dal vivo dal gioco e incursioni di BlazonGuild.",
  ["Niveles en vivo del juego; los grupos se comparten entre los miembros con el addon y con la web."] = "Livelli dal vivo dal gioco; i gruppi si condividono tra i membri con l'addon e con il web.",
  ["No"] = "No",
  ["No aceptar peticiones de capa"] = "Non accettare richieste di layer",
  ["No compartes tu posición."] = "Non condividi la tua posizione.",
  ["No cuenta para la Arena: %s no tiene BlazonGuild (el combate lo apunta el addon de quien pierde)."] = "Non conta per l'Arena: %s non ha BlazonGuild (il combattimento lo annota l'addon di chi perde).",
