  ["No hay campañas. Una campaña junta oro para algo concreto (por ejemplo, 100 de oro para pociones de banda) y enseña cuánto falta."] = "Nessuna campagna. Una campagna raccoglie oro per qualcosa di concreto (per esempio, 100 oro per pozioni d'incursione) e mostra quanto manca.",
  ["No hay cuota semanal. %s"] = "Nessuna quota settimanale. %s",
  ["No hay encargos. Pide un objeto a un artesano (o a quien sepa hacerlo): te avisamos cuando lo tome y cuando esté hecho."] = "Nessun ordine. Chiedi un oggetto a un artigiano (o a chi sa farlo): ti avvisiamo quando lo prende e quando è pronto.",
  ["No hay grupos abiertos ahora. Crea uno y tu hermandad podrá apuntarse por rol desde el juego."] = "Nessun gruppo aperto ora. Creane uno e la tua gilda potrà iscriversi per ruolo dal gioco.",
  ["No hay nada que elegir ahora."] = "Non c'è niente da scegliere ora.",
  ["No hay operaciones planeadas."] = "Nessuna operazione pianificata.",
  ["No hay operaciones. Las planean los organizadores y los jefes de escuadra; cuando haya una, te avisamos y respondes desde aquí."] = "Nessuna operazione. Le pianificano gli organizzatori e i capi squadra; quando ce ne sarà una, ti avvisiamo e rispondi da qui.",
  ["No hay operaciones. Planea una: qué se hace, cuándo, dónde y qué escuadras van. Cada uno responde «Voy», «Reserva» o «No puedo»."] = "Nessuna operazione. Pianificane una: cosa si fa, quando, dove e quali squadre vanno. Ognuno risponde «Vengo», «Riserva» o «Non posso».",
  ["No hay sitio"] = "Non c'è posto",
  ["No llegaste a la capa de %s. Puedes intentarlo de nuevo."] = "Non sei arrivato al layer di %s. Puoi riprovare.",
  ["No lleva tabardo."] = "Non indossa una tabarda.",
  ["No lo comparte. Pulsa «Ver su equipo»: si está cerca, lo inspeccionas; si está lejos y tiene BlazonGuild, se lo pedimos.%s"] = "Non lo condivide. Premi «Vedi il suo equipaggiamento»: se è vicino lo ispezioni; se è lontano e ha BlazonGuild, glielo chiediamo.%s",
  ["No lo comparte. Si lo tienes cerca (tu objetivo, el ratón encima o en tu grupo), pulsa «Inspeccionar»: lo verás tú, sin enviarlo a nadie.%s"] = "Non lo condivide. Se è vicino a te (il tuo bersaglio, sotto il mouse o nel tuo gruppo), premi «Ispeziona»: lo vedrai tu, senza inviarlo a nessuno.%s",
