  ["Sacerdote"] = "Sacerdote",
  ["Sal antes de tu grupo: la invitación es a uno nuevo."] = "Esci prima dal tuo gruppo: l'invito è per uno nuovo.",
  ["Sala"] = "Stanza",
  ["Sala de guerra"] = "Sala di guerra",
  ["Sala de guerra: la hermandad que lidera la alianza puede planear operaciones de toda la alianza; llegan a todas las hermandades y cada una responde en la suya."] = "Sala di guerra: la gilda che guida l'alleanza può pianificare operazioni di tutta l'alleanza; arrivano a tutte le gilde e ognuna risponde nella propria.",
  ["Salas"] = "Stanze",
  ["Salas, con la alianza"] = "Stanze, con l'alleanza",
  ["Saldo"] = "Saldo",
  ["Saldo para todos: %s"] = "Saldo per tutti: %s",
  ["Sale en el idioma de tu juego. En Administración, «Idioma del addon», eliges otro; se aplica al recargar la interfaz."] = "Appare nella lingua del tuo gioco. In Amministrazione, «Lingua dell'addon», ne scegli un'altra; si applica ricaricando l'interfaccia.",
  ["Salida"] = "Uscita",
  ["Salir"] = "Esci",
  ["Salir de la alianza"] = "Esci dall'alleanza",
  ["Salir de la cola"] = "Esci dalla coda",
  ["Salir de «%s»"] = "Esci da «%s»",
  ["Salto de capa sin terminar"] = "Cambio di layer incompiuto",
  ["Saludar por susurro"] = "Saluta con un sussurro",
  ["Salís en la clasificación. "] = "Siete in classifica. ",
  ["Salón de los Feudales"] = "Hall of Thanes",
  ["Sanador"] = "Guaritore",
  ["Sanadores"] = "Guaritori",
  ["Scholomance"] = "Scholomance",
  ["Se apunta solo cuando un tesorero recibe o da oro por comercio o por correo: entrada si se lo dan, salida si lo da él. El tesorero también puede apuntar a mano, y en cada línea poner el concepto (para qué es) y su campaña. «Copia de seguridad» saca el libro en texto para guardarlo fuera del juego."] = "Si annota da solo quando un tesoriere riceve o dà oro per scambio o per posta: entrata se glielo danno, uscita se lo dà lui. Il tesoriere può anche annotare a mano, e mettere su ogni riga la causale (a cosa serve) e la sua campagna. «Copia di sicurezza» esporta il registro come testo per conservarlo fuori dal gioco.",
  ["Se busca"] = "Ricercati",
  ["Se busca: %s"] = "Ricercato: %s",
  ["Se cuenta con lo que la hermandad ya apunta en BlazonGuild. Encima de cada ranking dice cómo se cuenta."] = "Si conta con ciò che la gilda già annota in BlazonGuild. Sopra ogni classifica c'è scritto come si conta.",
  ["Se guardan para poder corregirlos. Si me mandas una captura de esto, sé exactamente qué falló. Entre paréntesis, la versión del addon en la que pasó."] = "Si salvano per poterli correggere. Se mi mandi uno screenshot di questo, so esattamente cosa non ha funzionato. Tra parentesi, la versione dell'addon in cui è successo.",
  ["Se ha quitado de la Armería de tus compañeros."] = "È stato tolto dall'Armeria dei tuoi compagni.",
  ["Se juega por puntos: aquí no se apuesta oro."] = "Si gioca a punti: qui non si scommette oro.",
  ["Se lo hemos pedido"] = "Gliel'abbiamo chiesto",
  ["Se pregunta una vez por cuenta del juego. Cámbialo cuando quieras con /bg privacidad."] = "Si chiede una volta per account di gioco. Cambialo quando vuoi con /bg privacidad.",
  ["Se queda como cancelado para todos."] = "Resta annullato per tutti.",
  ["Se rindió"] = "Si è arreso",
  ["Se sincroniza entre los miembros con el addon y se refleja en la web."] = "Si sincronizza tra i membri con l'addon e si riflette sul web.",
  ["Se verá en cuanto el juego envíe la lista."] = "Si vedrà appena il gioco invia la lista.",
  ["Seguir"] = "Segui",
  ["Seguir a alguien"] = "Seguire qualcuno",
  ["Seguir compartiendo"] = "Continua a condividere",
  ["Seguir jugando"] = "Continua a giocare",
  ["Seguridad: nadie de otra hermandad puede meter nada en la vuestra (antes, un jugador de otra hermandad con el addon podía colaros un torneo, una sala de chat o un grupo)."] = "Sicurezza: nessuno di un'altra gilda può infilare niente nella vostra (prima, un giocatore di un'altra gilda con l'addon poteva infilarvi un torneo, una stanza di chat o un gruppo).",
  ["Semana tranquila por ahora: lo que pase aparecerá aquí."] = "Settimana tranquilla per ora: ciò che succede apparirà qui.",
  ["Semifinales"] = "Semifinali",
  ["Si acepta, empiezas tú."] = "Se accetta, inizi tu.",
  ["Si aceptas, os avisamos a los dos. El duelo lo empezáis desde el juego: clic derecho en su retrato, «Duelo»."] = "Se accetti, avvisiamo entrambi. Il duello lo iniziate dal gioco: clic destro sul suo ritratto, «Duello».",
  ["Si al tirar ningún dado puntúa, salen «huesos»: pierdes lo del turno y le toca al otro. Si guardas los seis, vuelves a tirarlos todos."] = "Se al lancio nessun dado fa punti, escono «ossa»: perdi i punti del turno e tocca all'altro. Se tieni tutti e sei, li ritiri tutti.",
  ["Si al tirar ningún dado puntúa: ¡huesos! Pierdes lo de este turno."] = "Se al lancio nessun dado fa punti: ossa! Perdi i punti di questo turno.",
  ["Si alguien de la otra facción te mata fuera de mazmorras y campos de batalla, tu addon lo apunta solo, con el resumen de muerte del juego. Ese jugador entra en la lista."] = "Se qualcuno dell'altra fazione ti uccide fuori dalle istanze e dai campi di battaglia, il tuo addon lo annota da solo, con il riepilogo di morte del gioco. Quel giocatore entra nella lista.",
  ["Si dejas de compartir, tu addon deja de enviar al momento. Lo que ya enviaste lo conservan tus compañeros hasta que caduque."] = "Se smetti di condividere, il tuo addon smette subito di inviare. Ciò che hai già inviato lo conservano i tuoi compagni finché non scade.",
  ["Si el maestro pone cuota (por ejemplo, 5 de oro por semana), en «Resumen» ves cuánto has dado esta semana y cuánto te falta."] = "Se il capogilda mette una quota (per esempio 5 oro a settimana), in «Riepilogo» vedi quanto hai dato questa settimana e quanto ti manca.",
  ["Si es un error, %s o un oficial puede quitarlo."] = "Se è un errore, %s o un ufficiale può toglierlo.",
  ["Si es un error, quien lo apuntó o un oficial puede quitarlo."] = "Se è un errore, chi l'ha annotato o un ufficiale può toglierlo.",
  ["Si instala BlazonGuild, podréis retaros y sus duelos contarán en la clasificación."] = "Se installa BlazonGuild, potrete sfidarvi e i suoi duelli conteranno nella classifica.",
  ["Si le cazas tú, te llevas la recompensa; y si un buscado anda cerca, te avisa."] = "Se lo cacci tu, ti prendi la taglia; e se un ricercato è nei paraggi, ti avvisa.",
  ["Si le das tú el golpe final, te llevas su recompensa más 1 punto, y su recompensa vuelve a cero. Los puntos de 90 días hacen el ranking de cazadores."] = "Se gli dai tu il colpo di grazia, ti prendi la sua taglia più 1 punto, e la sua taglia torna a zero. I punti di 90 giorni fanno la classifica dei cacciatori.",
  ["Si le invitas, el addon le saca del grupo al llegar."] = "Se lo inviti, l'addon lo toglie dal gruppo quando arriva.",
  ["Si le matas tú, te llevas %s puntos de cazador."] = "Se lo uccidi tu, ti prendi %s punti da cacciatore.",
  ["Si quieres ayudar, da oro a un tesorero (comercio o correo): se apunta solo."] = "Se vuoi aiutare, dai oro a un tesoriere (scambio o posta): si annota da solo.",
  ["Si quieres, compartes tu posición y tu capa con la hermandad: salís como puntos en el mapa del mundo."] = "Se vuoi, condividi la tua posizione e il tuo layer con la gilda: comparite come punti sulla mappa del mondo.",
  ["Si sales ahora, gana %s."] = "Se esci ora, vince %s.",
  ["Si tu hermandad usa puntos de botín, los organizadores los apuntan a mano: nada los suma ni los resta solo. Sin pujas ni oro."] = "Se la tua gilda usa punti bottino, gli organizzatori li annotano a mano: niente li somma né li toglie da solo. Senza offerte né oro.",
  ["Si vuestro maestro lo activa, unas cifras de la hermandad (cuántos sois, jefes derrotados…; nada de nadie en concreto) salen en la clasificación de hermandades, para quien juegue en grupo con vosotros."] = "Se il vostro capogilda lo attiva, alcuni numeri della gilda (quanti siete, boss sconfitti…; niente di nessuno in particolare) compaiono nella classifica delle gilde, per chi gioca in gruppo con voi.",
  ["Siguiente"] = "Avanti",
  ["Silenciado"] = "Silenziato",
  ["Silenciado %s"] = "Silenziato %s",
  ["Silenciarle en las salas de BlazonGuild suma un aviso; al tercero se abre un caso que decide el maestro. Si comparte su BattleTag con los organizadores, alcanza a todos sus personajes."] = "Silenziarlo nelle stanze di BlazonGuild aggiunge un avviso; al terzo si apre un caso che decide il capogilda. Se condivide il suo BattleTag con gli organizzatori, vale per tutti i suoi personaggi.",
  ["Sima Ígnea"] = "Voragine Ardente",
  ["Sin aceptar: el addon no envía nada"] = "Non accettato: l'addon non invia nulla",
  ["Sin alianza"] = "Senza alleanza",
  ["Sin anuncios todavía. Los publican el maestro y los organizadores."] = "Ancora nessun annuncio. Li pubblicano il capogilda e gli organizzatori.",
  ["Sin anuncios. Publica el primero: toda la hermandad lo verá y sabrás quién lo ha leído."] = "Nessun annuncio. Pubblica il primo: tutta la gilda lo vedrà e saprai chi l'ha letto.",
  ["Sin cargo"] = "Senza carica",
  ["Sin cargos. Los capitanes leen y escriben en «Oficiales de la alianza»; los mensajeros llevan los mensajes a las otras hermandades."] = "Nessuna carica. I capitani leggono e scrivono in «Ufficiali dell'alleanza»; i messaggeri portano i messaggi alle altre gilde.",
  ["Sin combate"] = "Nessun combattimento",
  ["Sin compartir con tu hermandad: pulsa aquí"] = "Non condiviso con la tua gilda: premi qui",
  ["Sin concepto"] = "Senza causale",
  ["Sin decir"] = "Non specificato",
  ["Sin denuncias recibidas ni nadie silenciado ahora."] = "Nessuna segnalazione ricevuta e nessuno silenziato ora.",
  ["Sin festividades en estas dos semanas."] = "Nessuna festività in queste due settimane.",
  ["Sin grupo"] = "Senza gruppo",
  ["Sin hermandad"] = "Senza gilda",
  ["Sin invitación"] = "Senza invito",
  ["Sin motivo anotado"] = "Nessun motivo annotato",
  ["Sin notas. Apunta a quién se dio cada objeto y por qué: la próxima banda empieza de lo decidido."] = "Nessuna nota. Annota a chi è andato ogni oggetto e perché: la prossima incursione parte da quanto deciso.",
  ["Sin notas. Los organizadores apuntan aquí a quién se dio cada objeto y por qué."] = "Nessuna nota. Gli organizzatori annotano qui a chi è andato ogni oggetto e perché.",
  ["Sin organizadores conectados"] = "Nessun organizzatore connesso",
  ["Sin peticiones todavía"] = "Ancora nessuna richiesta",
  ["Sin probar en esta sesión"] = "Non provato in questa sessione",
  ["Sin raids próximas ni bandera en el tablón."] = "Nessuna incursione in arrivo né bandiera in bacheca.",
  ["Sin respuesta"] = "Nessuna risposta",
  ["Sin zona"] = "Senza zona",
  ["Sin árbitros: deciden los combates a mano quien dirige cada torneo y los organizadores."] = "Nessun arbitro: decidono a mano gli incontri chi dirige ogni torneo e gli organizzatori.",
  ["Sobre esta persona"] = "Su questa persona",
  ["Sobre los miembros de la hermandad sale vuestro escudo. Si no quieres ver las marcas (tampoco las del chat), quítalas abajo o con /bg marcas."] = "Sopra i membri della gilda compare il vostro stemma. Se non vuoi vedere i segni (nemmeno quelli della chat), toglili qui sotto o con /bg marcas.",
  ["Solo %s"] = "Solo %s",
  ["Solo %s y %s: lo leen los miembros de las dos con BlazonGuild. %s"] = "Solo %s e %s: lo leggono i membri di entrambe con BlazonGuild. %s",
  ["Solo aparece quien lo tiene instalado, está conectado y ha aceptado la privacidad."] = "Compare solo chi l'ha installato, è connesso e ha accettato la privacy.",
  ["Solo borrar el mensaje"] = "Cancella solo il messaggio",
  ["Solo con miembros de tu hermandad que tengan el addon (y, más adelante, con las hermandades aliadas que acepte tu maestro)."] = "Solo con membri della tua gilda che hanno l'addon (e, più avanti, con le gilde alleate che il tuo capogilda accetta).",
  ["Solo con miembros de tu hermandad que tengan el addon. Si vuestro maestro forma una alianza, también el chat de la alianza y quién está conectado, con esas hermandades; con ninguna otra."] = "Solo con i membri della tua gilda che hanno l'addon. Se il vostro capogilda forma un'alleanza, anche la chat dell'alleanza e chi è connesso, con quelle gilde; con nessun'altra.",
  ["Solo cuando el addon de un miembro ve que le mata alguien de la otra facción fuera de mazmorras y campos de batalla. Nadie puede apuntar a otro a mano."] = "Solo quando l'addon di un membro vede che lo uccide qualcuno dell'altra fazione fuori dalle istanze e dai campi di battaglia. Nessuno può aggiungere un altro a mano.",
  ["Solo el líder de la raid, quien la creó y los oficiales pueden moverlos."] = "Solo il leader dell'incursione, chi l'ha creata e gli ufficiali possono spostarli.",
  ["Solo el maestro de la hermandad puede cambiarlo."] = "Solo il capogilda può cambiarlo.",
  ["Solo el maestro de la hermandad puede hacerlo."] = "Solo il capogilda può farlo.",
  ["Solo el maestro decide si la hermandad sale en la clasificación."] = "Solo il capogilda decide se la gilda compare in classifica.",
  ["Solo el maestro%s puede crear una alianza o aceptar una invitación. Si conoces una hermandad amiga, cuéntaselo."] = "Solo il capogilda%s può creare un'alleanza o accettare un invito. Se conosci una gilda amica, diglielo.",
  ["Solo lo que llevas puesto, como lo ve cualquiera que te inspeccione en el juego."] = "Solo ciò che indossi, come lo vede chiunque ti ispezioni nel gioco.",
  ["Solo lo ven los rangos que leen el chat de oficiales."] = "Lo vedono solo i ranghi che leggono la chat degli ufficiali.",
  ["Solo los maestros de las hermandades de la alianza."] = "Solo i capigilda delle gilde dell'alleanza.",
  ["Solo los oficiales pueden hacerlo."] = "Solo gli ufficiali possono farlo.",
  ["Solo los oficiales sortean."] = "Solo gli ufficiali estraggono.",
  ["Solo los oficiales ven quién ha pagado. Tu propia cuota está en «Resumen»."] = "Solo gli ufficiali vedono chi ha pagato. La tua quota è in «Riepilogo».",
  ["Solo los organizadores de la hermandad que lidera la alianza."] = "Solo gli organizzatori della gilda che guida l'alleanza.",
  ["Solo los organizadores publican anuncios."] = "Solo gli organizzatori pubblicano annunci.",
  ["Solo los organizadores pueden hacerlo."] = "Solo gli organizzatori possono farlo.",
  ["Solo quien lo apuntó o un oficial puede quitarlo."] = "Solo chi l'ha annotato o un ufficiale può toglierlo.",
  ["Solo quien lo dirige y los oficiales pueden hacerlo."] = "Solo chi lo dirige e gli ufficiali possono farlo.",
  ["Solo si lo activas en Mapa («Compartir mi posición y mi capa»), y solo tu hermandad. Está apagado hasta que lo enciendes."] = "Solo se lo attivi in Mappa («Condividi la mia posizione e il mio layer»), e solo la tua gilda. È spento finché non lo accendi.",
  ["Solo si lo activas en Mapa («Compartir mi posición»), y solo tu hermandad: te ven como un punto en su mapa y su minimapa. Está apagado hasta que lo enciendes."] = "Solo se lo attivi in Mappa («Condividi la mia posizione»), e solo la tua gilda: ti vedono come un punto sulla mappa e sulla minimappa. È spento finché non lo accendi.",
  ["Solo tu escuadra: %s (jefe) y %s%s. Va por susurro a cada uno: nadie más lo lee."] = "Solo la tua squadra: %s (capo) e %s%s. Va per sussurro a ciascuno: nessun altro lo legge.",
  ["Solo. Al terminar un duelo entre dos de la hermandad, el juego dice quién ganó y el addon de quien pierde lo apunta. Así nadie puede darse victorias."] = "Da solo. Alla fine di un duello tra due della gilda, il gioco dice chi ha vinto e l'addon di chi perde lo annota. Così nessuno può darsi vittorie.",
  ["Sorteando… (%s tiradas)"] = "Sorteggio… (%s tiri)",
  ["Sortear hoy"] = "Estrai oggi",
  ["Sortear y empezar"] = "Sorteggia e inizia",
  ["Sorteo con /roll: %s. "] = "Sorteggio con /roll: %s. ",
  ["Stratholme"] = "Stratholme",
  ["Su addon apunta el combate: lo verás en la Arena en un momento."] = "Il suo addon annota il combattimento: lo vedrai nell'Arena tra un momento.",
  ["Su ficha"] = "La sua scheda",
  ["Su mejor victoria: contra %s, que tenía %s."] = "La sua miglior vittoria: contro %s, che aveva %s.",
  ["Su recompensa"] = "La sua taglia",
  ["Su sala de chat: en Chat, «%s»."] = "La sua stanza di chat: in Chat, «%s».",
  ["Subir de nivel juntos"] = "Salire di livello insieme",
  ["Suele jugar: %s"] = "Di solito gioca: %s",
  ["Sus mensajes no salen en los chats comunes de la alianza."] = "I loro messaggi non compaiono nelle chat comuni dell'alleanza.",
  ["Sus miembros quedan libres para otras escuadras. Las operaciones ya planeadas siguen."] = "I suoi membri restano liberi per altre squadre. Le operazioni già pianificate continuano.",
  ["Sus personajes"] = "I suoi personaggi",
  ["Susurrar"] = "Sussurra",
  ["Sí"] = "Sì",
  ["Sí. Con la interfaz de mando del juego, BlazonGuild no toca los menús, las placas ni el chat del juego (es lo que da problemas); su ventana, el mapa y los avisos siguen igual."] = "Sì. Con l'interfaccia controller del gioco, BlazonGuild non tocca menu, targhette né chat del gioco (è ciò che dà problemi); la sua finestra, la mappa e gli avvisi restano uguali.",
  ["Sí: lo que tu hermandad publica desde el juego aparece en la web de BlazonGuild a través de la app puente."] = "Sì: ciò che la tua gilda pubblica dal gioco appare sul sito di BlazonGuild tramite l'app ponte.",
  ["Tabardo"] = "Tabarda",
  ["Taberna"] = "Taverna",
  ["Taberna: los Huesos tienen mesa nueva, con dados que caen, ruedan y brillan si puntúan, los pasos del turno a la vista y «Cómo se juega»."] = "Taverna: Ossa ha un tavolo nuovo, con dadi che cadono, rotolano e brillano se fanno punti, i passi del turno in vista e «Come si gioca».",
  ["Tablón"] = "Bacheca",
  ["Tablón de %s"] = "Bacheca di %s",
  ["Tablón%s"] = "Bacheca%s",
  ["También puedes recargarla más tarde con /reload."] = "Puoi anche ricaricarla più tardi con /reload.",
  ["También: /bg o la tecla que asignes en Atajos > Accesorios"] = "Anche: /bg o il tasto che assegni in Tasti di scelta rapida > AddOn",
  ["Tanaris"] = "Tanaris",
  ["Tanque"] = "Tank",
  ["Tanques"] = "Tank",
  ["Te ha ganado %s"] = "%s ti ha battuto",
  ["Te ha matado %s"] = "%s ti ha ucciso",
  ["Te hacen un encargo"] = "Ti fanno un ordine",
  ["Te han aceptado"] = "Ti hanno accettato",
  ["Te has rendido. "] = "Ti sei arreso. ",
  ["Te matan"] = "Ti uccidono",
  ["Te retan"] = "Ti sfidano",
  ["Te toca. "] = "Tocca a te. ",
  ["Te toca: tira %d %s"] = "Tocca a te: tira %d %s",
  ["Te trajo: %s. Puedes cambiarlo."] = "Ti ha portato: %s. Puoi cambiarlo.",
  ["Templo de Ahn'Qiraj"] = "Tempio di Ahn'Qiraj",
  ["Templo de Atal'Hakkar"] = "Il Tempio di Atal'Hakkar",
  ["Temporada %s"] = "Stagione %s",
  ["Temporada %s%s: %s%s"] = "Stagione %s%s: %s%s",
  ["Temporada %s: campeón %s%s."] = "Stagione %s: campione %s%s.",
  ["Tendréis un chat común, con una pestaña para cada hermandad."] = "Avrete una chat comune, con una scheda per ogni gilda.",
  ["Tenías una ficha en %s (tu presentación, tu rol, cuándo juegas)."] = "Avevi una scheda in %s (la tua presentazione, il tuo ruolo, quando giochi).",
  ["Tercer aviso: %s"] = "Terzo avviso: %s",
  ["Termina antes tu partida."] = "Finisci prima la tua partita.",
  ["Terminada"] = "Finita",
  ["Terminado"] = "Finito",
  ["Terminar"] = "Termina",
  ["Terminar y guardar el parte"] = "Termina e salva il rapporto",
  ["Tesoreros (nombres separados por comas)"] = "Tesorieri (nomi separati da virgole)",
  ["Tesoreros: %s. "] = "Tesorieri: %s. ",
  ["Tesorería"] = "Tesoreria",
  ["Tesorería: el oro se escribe también como 2g 50s. Autoprueba: dice cómo escribe tu juego los nombres."] = "Tesoreria: l'oro si scrive anche come 2g 50s. Autotest: dice come il tuo gioco scrive i nomi.",
  ["Tesorería: las cantidades ya caben en sus cuadros. Rankings: los 10 primeros de cada honor, y ya no está el del nivel 60."] = "Tesoreria: gli importi ora stanno nei loro riquadri. Classifiche: i primi 10 di ogni onore, e quello del livello 60 non c'è più.",
  ["Texto (opcional)"] = "Testo (facoltativo)",
  ["The Barrow Deeps"] = "The Barrow Deeps",
  ["Tiene que estar cerca de ti (tu objetivo, el ratón encima o en tu grupo)."] = "Deve essere vicino a te (il tuo bersaglio, sotto il mouse o nel tuo gruppo).",
  ["Tiene que estar conectado y con BlazonGuild."] = "Deve essere connesso e avere BlazonGuild.",
  ["Tienes la palabra"] = "Hai la parola",
  ["Tienes que ser líder o ayudante de la banda."] = "Devi essere capo o assistente dell'incursione.",
  ["Tierras Inhóspitas"] = "Maleterre",
  ["Tierras de la Peste del Este"] = "Terre Infette Orientali",
  ["Tierras de la Peste del Oeste"] = "Terre Infette Occidentali",
  ["Tipo %s"] = "Tipo %s",
  ["Tira los dados."] = "Tira i dadi.",
  ["Tira los que quedan, o plántate y súmalo."] = "Tira gli altri, o fermati e sommali.",
  ["Tira seis dados, aparta los que puntúan y decide: arriesgar con el resto o plantarte. Si una tirada no da nada, pierdes lo del turno. Gana quien llega a %s. Los dados salen del /roll del juego."] = "Tira sei dadi, metti da parte quelli che fanno punti e decidi: rischiare con il resto o fermarti. Se un tiro non dà niente, perdi i punti del turno. Vince chi arriva a %s. I dadi escono dal /roll del gioco.",
  ["Tirando…"] = "Tiro in corso…",
  ["Tirar"] = "Tira",
  ["Tirar %d %s"] = "Tira %d %s",
  ["Tirar %s%s"] = "Tira %s%s",
  ["Toda la alianza"] = "Tutta l'alleanza",
