  ["Toda la hermandad"] = "Tutta la gilda",
  ["Todavía no ha escrito nada sobre sí."] = "Non ha ancora scritto nulla di sé.",
  ["Todavía no has escrito nada. Pulsa «Editar mi ficha»."] = "Non hai ancora scritto nulla. Premi «Modifica la mia scheda».",
  ["Todavía no hay mensajes en esta sesión. Lo que se diga en el chat de hermandad aparecerá aquí."] = "Ancora nessun messaggio in questa sessione. Ciò che si dice nella chat di gilda apparirà qui.",
  ["Todavía no hay raids programadas en %s."] = "Ancora nessuna incursione programmata in %s.",
  ["Todos"] = "Tutti",
  ["Todos empiezan con %s puntos. Ganar a alguien mejor que tú da más puntos; a alguien de más nivel, también."] = "Tutti partono da %s punti. Battere qualcuno migliore di te dà più punti; anche qualcuno di livello più alto.",
  ["Todos empiezan con 1500. Ganar a alguien mejor da más puntos. Por ejemplo, en tus primeros combates y con el mismo nivel: ganar a uno de 1600 da unos 26; a uno de 1400, unos 14."] = "Tutti partono da 1500. Battere qualcuno migliore dà più punti. Per esempio, nei tuoi primi combattimenti e allo stesso livello: battere uno con 1600 dà circa 26; uno con 1400, circa 14.",
  ["Todos empiezan de cero. ¡Suerte!"] = "Tutti ripartono da zero. Buona fortuna!",
  ["Todos los apuntados tienen grupo."] = "Tutti gli iscritti hanno un gruppo.",
  ["Todos los mensajes de la alianza llevan una marca hecha con su clave. Cámbiala si crees que la conoce alguien de fuera."] = "Tutti i messaggi dell'alleanza portano un segno fatto con la sua chiave. Cambiala se pensi che qualcuno da fuori la conosca.",
  ["Todos ven los grupos; los mueven el líder de la raid, quien la creó y los oficiales."] = "Tutti vedono i gruppi; li spostano il leader dell'incursione, chi l'ha creata e gli ufficiali.",
  ["Todos vuelven a empezar con %s puntos."] = "Tutti ripartono con %s punti.",
  ["Torneo"] = "Torneo",
  ["Torneo, %s"] = "Torneo, %s",
  ["Torneo: %s"] = "Torneo: %s",
  ["Torneo: cada uno se apunta; al sortear sale el cuadro eliminatorio."] = "Torneo: ognuno si iscrive; al sorteggio esce il tabellone a eliminazione diretta.",
  ["Torneos"] = "Tornei",
  ["Torneos y veladas"] = "Tornei e serate",
  ["Traerla"] = "Portala",
  ["Tres iguales: la cara × 100 (tres 4 = 400); tres 1 = 1000. Cada dado igual de más lo dobla."] = "Tre uguali: la faccia × 100 (tre 4 = 400); tre 1 = 1000. Ogni dado uguale in più raddoppia.",
  ["Tu addon apunta solo lo tuyo, con el resumen de muerte y tu golpe final."] = "Il tuo addon annota solo ciò che è tuo, con il riepilogo di morte e il tuo colpo di grazia.",
  ["Tu bandera en el tablón"] = "La tua bandiera in bacheca",
  ["Tu equipo y su nivel"] = "Il tuo equipaggiamento e il suo livello",
  ["Tu ficha"] = "La tua scheda",
  ["Tu firma aún no está en la alianza. La añade vuestro maestro la próxima vez que se conecte."] = "La tua firma non è ancora nell'alleanza. La aggiunge il vostro capogilda la prossima volta che si connette.",
  ["Tu grupo"] = "Il tuo gruppo",
  ["Tu grupo: %s"] = "Il tuo gruppo: %s",
  ["Tu hermandad"] = "La tua gilda",
  ["Tu hermandad dejará de ver el chat de la alianza y sus salas compartidas. Las demás hermandades siguen juntas."] = "La tua gilda non vedrà più la chat dell'alleanza e le sue stanze condivise. Le altre gilde restano insieme.",
  ["Tu hermandad ve lo que llevas puesto en la Armería; se actualiza cuando cambias algo."] = "La tua gilda vede cosa indossi nell'Armeria; si aggiorna quando cambi qualcosa.",
  ["Tu hermandad verá en «Artesanía y botín» lo que sabes fabricar de %s (%s/%s)."] = "La tua gilda vedrà in «Artigianato e bottino» cosa sai fabbricare con %s (%s/%s).",
  ["Tu inscripción"] = "La tua iscrizione",
  ["Tu mensaje volvió en %d ms. Ningún otro miembro conectado tiene BlazonGuild ahora."] = "Il tuo messaggio è tornato in %d ms. Nessun altro membro connesso ha BlazonGuild ora.",
  ["Tu nuevo rango, %s, es de organizador en BlazonGuild. A partir de ahora puedes:"] = "Il tuo nuovo rango, %s, è da organizzatore in BlazonGuild. Da ora puoi:",
  ["Tu posición en el mapa"] = "La tua posizione sulla mappa",
  ["Tu rol en el grupo"] = "Il tuo ruolo nel gruppo",
  ["Tu rol habitual"] = "Il tuo ruolo abituale",
  ["Tu vista"] = "La tua vista",
  ["Tu voto dice que el maestro de %s lidere la alianza."] = "Il tuo voto dice che il capogilda di %s guidi l'alleanza.",
  ["Tu voto es para %s."] = "Il tuo voto è per %s.",
