  ["Uldaman"] = "Uldaman",
  ["Un 1 vale 100 y un 5 vale 50."] = "Un 1 vale 100 e un 5 vale 50.",
  ["Un duelo"] = "Un duello",
  ["Un juego de dados de taberna. Tiras seis dados, guardas los que puntúan y decides: arriesgar con los que quedan o plantarte. Gana quien llega a %s. Los dados salen del /roll del juego, así que nadie hace trampas."] = "Un gioco di dadi da taverna. Tiri sei dadi, tieni quelli che fanno punti e decidi: rischiare con gli altri o fermarti. Vince chi arriva a %s. I dadi escono dal /roll del gioco, quindi nessuno bara.",
  ["Un jugador sin hermandad abre BlazonGuild, escribe vuestro nombre y ve vuestra ficha. Necesita que alguno de vosotros esté conectado con el addon."] = "Un giocatore senza gilda apre BlazonGuild, scrive il vostro nome e vede la vostra scheda. Serve che uno di voi sia connesso con l'addon.",
  ["Un momento: escribes muy rápido."] = "Un momento: scrivi molto in fretta.",
  ["Un ordenador con personajes en varias hermandades guarda lo de cada una por separado, también si dos se llaman igual."] = "Un computer con personaggi in più gilde tiene separati i dati di ognuna, anche se due si chiamano allo stesso modo.",
  ["Una alianza une tu hermandad con otras: chat común, una pestaña para cada hermandad y salas compartidas. Cada una sigue con su maestro."] = "Un'alleanza unisce la tua gilda ad altre: chat comune, una scheda per ogni gilda e stanze condivise. Ognuna mantiene il suo capogilda.",
  ["Una campaña junta oro para algo concreto, con su barra de progreso. En «Banco» ves lo que había la última vez que un oficial lo abrió."] = "Una campagna raccoglie oro per qualcosa di concreto, con la sua barra di avanzamento. In «Banca» vedi cosa c'era l'ultima volta che un ufficiale l'ha aperta.",
  ["Una capa es una copia de la zona. Para jugar con alguien de otra, pídele invitación: él decide, y el addon te saca del grupo al llegar."] = "Un layer è una copia della zona. Per giocare con qualcuno di un altro, chiedigli un invito: decide lui, e l'addon ti toglie dal gruppo all'arrivo.",
  ["Una capa es una copia de la zona. Para saber la tuya no hace falta tocar nada aquí: en el juego, haz clic en dos personajes que no sean jugadores (un guardia, un vendedor, un bicho) o pasa el ratón por encima de ellos.%s"] = "Un layer è una copia della zona. Per sapere il tuo non serve toccare niente qui: nel gioco, clicca su due personaggi che non siano giocatori (una guardia, un venditore, una bestiola) o passaci sopra con il mouse.%s",
  ["Una capa es una copia de la zona. Para saber la tuya, haz clic en el juego en dos personajes que no sean jugadores (por ejemplo, dos guardias)."] = "Un layer è una copia della zona. Per sapere il tuo, clicca nel gioco su due personaggi che non siano giocatori (per esempio, due guardie).",
  ["Una guía corta de esta sección, paso a paso."] = "Una breve guida di questa sezione, passo dopo passo.",
  ["Una hermandad de ejemplo con nombres inventados, solo en tu pantalla, para hacer capturas de cada pantalla. No sale nada de tu juego. Vuelve a la tuya con el mismo botón o /bg capturas."] = "Una gilda di esempio con nomi inventati, solo sul tuo schermo, per fare screenshot di ogni schermata. Niente esce dal tuo gioco. Torna alla tua con lo stesso pulsante o /bg capturas.",
  ["Una hermandad de ejemplo, solo en tu pantalla: nombres inventados y nada sale de tu juego. Vuelve a la tuya con /bg capturas."] = "Una gilda di esempio, solo sul tuo schermo: nomi inventati e niente esce dal tuo gioco. Torna alla tua con /bg capturas.",
  ["Una hermandad sale de la alianza"] = "Una gilda esce dall'alleanza",
  ["Una partida de Huesos, a %s."] = "Una partita a Ossa, a %s.",
  ["Una partida de dados por puntos (a 3000). Ábrelo en la Arena, pestaña «Taberna»."] = "Una partita a dadi a punti (a 3000). Aprila nell'Arena, scheda «Taverna».",
  ["Una raid cancelada se ve cancelada: solo su cabecera con «CANCELADA» y, para quien la gestiona, «Volver a programar» y «Borrar»."] = "Un'incursione annullata si vede annullata: solo la sua intestazione con «ANNULLATA» e, per chi la gestisce, «Riprogramma» ed «Elimina».",
  ["Unas palabras para sus oficiales (opcional)"] = "Qualche parola per i loro ufficiali (facoltativa)",
  ["Unas palabras sobre ti (lo verá tu hermandad)"] = "Qualche parola su di te (la vedrà la tua gilda)",
  ["Une %s con otras hermandades: chat común, salas compartidas y quién está conectado en todas."] = "Unisci %s ad altre gilde: chat comune, stanze condivise e chi è connesso in tutte.",
