  ["«%s» ya no puede leer BlazonGuild."] = "«%s» non può più leggere BlazonGuild.",
  ["«%s», %s. El parte queda en la crónica de la hermandad."] = "«%s», %s. Il rapporto resta nella cronaca della gilda.",
  ["«%s»: %s hermandades, en contacto con %s"] = "«%s»: %s gilde, in contatto con %s",
  ["«Cara a cara» pone a dos luchadores uno frente al otro, con su vida en directo si los tienes cerca y quién gana al acabar. Se puede agrandar para retransmitir."] = "«Faccia a faccia» mette due combattenti uno di fronte all'altro, con la vita in diretta se sono vicini e chi vince alla fine. Si può ingrandire per trasmettere.",
  ["«Colocar en la banda» mueve a la gente a sus grupos de verdad cuando la banda ya está formada (líder o ayudante, fuera de combate)."] = "«Colloca nell'incursione» sposta la gente nei suoi gruppi veri quando l'incursione è già formata (capo o assistente, fuori combattimento).",
  ["«Copiar» y luego Ctrl+C: pégalo donde quieras."] = "«Copia» e poi Ctrl+C: incollalo dove vuoi.",
  ["«Grupos» enseña los grupos de la banda como en el juego. El líder de la raid, quien la creó y los oficiales arrastran a cada uno a su grupo y su fila (o lo pulsan y luego pulsan dónde va)."] = "«Gruppi» mostra i gruppi dell'incursione come nel gioco. Il leader dell'incursione, chi l'ha creata e gli ufficiali trascinano ognuno nel suo gruppo e nella sua riga (o lo premono e poi premono dove va).",
  ["«Invitar confirmados» invita a los que van y están conectados, y convierte el grupo en banda."] = "«Invita confermati» invita chi viene ed è connesso, e trasforma il gruppo in incursione.",
  ["«Mazmorras» ahora se llama Grupos: también para JcJ, misiones, subir de nivel o farmear."] = "«Istanze» ora si chiama Gruppi: anche per PvP, missioni, salire di livello o farmare.",
  ["«Retar» le manda tu reto; el duelo lo empezáis desde el juego."] = "«Sfida» gli manda la tua sfida; il duello lo iniziate dal gioco.",
  ["«Se busca»"] = "«Ricercati»",
  ["«Ver su ficha» en el menú del botón derecho del juego"] = "«Vedi la sua scheda» nel menu del clic destro del gioco",
  ["«Ver un duelo» (o /bg duelo): el cara a cara del duelo de tu objetivo. Y en cada torneo o velada, «Cara a cara del siguiente combate»."] = "«Guarda un duello» (o /bg duelo): il faccia a faccia del duello del tuo bersaglio. E in ogni torneo o serata, «Faccia a faccia del prossimo incontro».",
  ["«¡A las armas!» y «Reunión aquí» para los organizadores, con alerta y marca en el mapa."] = "«Alle armi!» e «Riunione qui» per gli organizzatori, con allerta e segno sulla mappa.",
  ["· Ahora la comparten %s%s"] = "· Ora la condividono %s%s",
  ["· Las salas de Sanadores, Tanques, Daño, Comercio y Ayuda se comparten."] = "· Le stanze Guaritori, Tank, Danni, Commercio e Aiuto sono condivise.",
  ["· Los maestros eligen un líder, que puede llamar a las armas a toda la alianza."] = "· I capigilda scelgono un leader, che può chiamare alle armi tutta l'alleanza.",
  ["· Los oficiales de todas tienen su canal, y los maestros el suyo."] = "· Gli ufficiali di tutte hanno il loro canale, e i capigilda il loro.",
  ["· Quien la comparte sale como un punto de su color de clase en el mapa del mundo (tecla M) de sus compañeros con BlazonGuild."] = "· Chi la condivide compare come un punto del colore della sua classe sulla mappa del mondo (tasto M) dei compagni con BlazonGuild.",
  ["· Solo tu hermandad; nunca dentro de mazmorras. Tú no ves tu punto: el juego ya te marca."] = "· Solo la tua gilda; mai dentro le istanze. Il tuo punto non lo vedi: il gioco ti segna già.",
  ["· Un chat común: una pestaña para toda la alianza y otra para cada hermandad hermana."] = "· Una chat comune: una scheda per tutta l'alleanza e un'altra per ogni gilda sorella.",
